50	func main() {
51		if err := run(); err != nil {
52			fmt.Fprintln(os.Stderr, "forgemark: "+err.Error())
53			os.Exit(1)
54		}
55	}
56	
57	type runConfig struct {
58		remote       string
59		tokenFile    string // path to the credential secret ("-" = stdin); preferred over $ACCESS_TOKEN
60		user         string // basic-auth username (default x-access-token; token forges ignore it)
61		repos        []string
62		strategy     string
63		branchPrefix string
64		concurrency  []int
65		duration     time.Duration
66		warmup       time.Duration
67		commit       commitConfig
68		objectFmt    string
69		insecure     bool
70		out          string
71		runID        string
72	
73		// session strategy
74		sessionCommits int
75		cloneDepth     int
76		baseRef        string
77	
78		// entiredb: supplying -jurisdiction/-token-url selects the entiredb path
79		// (jurisdiction-token exchange + node discovery). Meaningless to any other
80		// forge, so their presence is the signal — no separate -target flag.
81		tokenURL     string
82		jurisdiction string
83		clientID     string
84	}
85	
86	func run() error {
87		cfg, err := parseFlags()
88		if err != nil {
89			return err
90		}
91	
92		httpc := newHTTPClient(cfg.insecure, maxInt(cfg.concurrency)+8)
93	
94		ctx, stop := signal.NotifyContext(context.Background(), syscall.SIGINT, syscall.SIGTERM)
95		defer stop()
96	
97		creds, ep, err := setupTarget(ctx, cfg, httpc)
98		if err != nil {
99			return err
100		}
101	
102		fmt.Printf("forgemark: target=%s strategy=%s repos=%d nodes=%d object-format=%s commit=%s\n",
103			ep.label, cfg.strategy, len(cfg.repos), len(ep.nodes), ep.objFmt, cfg.commitDesc())
104		fmt.Printf("           sweep=%v duration=%s warmup=%s\n", cfg.concurrency, cfg.duration, cfg.warmup)
105		fmt.Println()
106	
107		var results []levelResult
108		for _, c := range cfg.concurrency {
109			if ctx.Err() != nil {
110				break
111			}
112			res, err := runLevel(ctx, cfg, creds, ep, httpc, c)
113			if err != nil {
114				return fmt.Errorf("concurrency=%d: %w", c, err)
115			}
116			results = append(results, res)
117			printRow(res)
118		}
119	
120		return writeResults(cfg, ep, results)
121	}
122	
123	// setupTarget builds the credential provider and resolved endpoint, inferring
124	// the forge from the flags rather than an explicit switch:
125	//
126	//   - Supplying -jurisdiction or -token-url selects entiredb (they mean nothing
127	//     to any other forge). A partial set is a hard error, not a silent fallback.
128	//   - Otherwise it's a plain smart-HTTP forge with a static credential. If the
129	//     remote host is github.com, the abuse-detection warning applies — that's
130	//     the only thing that ever distinguished "github".
131	func setupTarget(ctx context.Context, cfg *runConfig, httpc *http.Client) (credentialProvider, *endpoint, error) {
132		if cfg.tokenURL != "" || cfg.jurisdiction != "" {
133			return setupEntiredb(ctx, cfg, httpc)
134		}
135		return setupGeneric(cfg)
136	}
137	
138	func setupGeneric(cfg *runConfig) (credentialProvider, *endpoint, error) {
139		if cfg.remote == "" {
140			return nil, nil, errors.New("-remote required (e.g. https://gitlab.com); for entiredb also pass -token-url and -jurisdiction")
141		}
142		github := isGitHubDotCom(cfg.remote)
143		if github && cfg.objectFmt == "sha256" {
144			return nil, nil, errors.New("github.com is sha1; drop -object-format sha256")
145		}
146		if github {
147			if hi := maxInt(cfg.concurrency); hi > 16 {
148				fmt.Fprintf(os.Stderr, "forgemark: warning: concurrency %d against github.com is likely to trip "+
149					"secondary rate limits / abuse detection — keep it low (e.g. -concurrency 1,4)\n", hi)
150			}
151		}
152		objFmt, err := parseObjectFormat(cfg.objectFmt)
153		if err != nil {
154			return nil, nil, err
155		}
156		secret, err := readSecret(cfg)
157		if err != nil {
158			return nil, nil, err
159		}
160		user := cfg.user
161		if user == "" {
162			user = "x-access-token" // token forges ignore the username; the token is the password
163		}
164		return staticCreds{username: user, password: secret}, newGenericEndpoint(cfg.remote, objFmt), nil
165	}
166	
167	func setupEntiredb(ctx context.Context, cfg *runConfig, httpc *http.Client) (credentialProvider, *endpoint, error) {
168		var missing []string
169		if cfg.remote == "" {
170			missing = append(missing, "-remote (cluster base URL)")
171		}
172		if cfg.tokenURL == "" {
173			missing = append(missing, "-token-url")
174		}
175		if cfg.jurisdiction == "" {
176			missing = append(missing, "-jurisdiction")
177		}
178		if len(missing) > 0 {
179			return nil, nil, fmt.Errorf("entire target (selected by -token-url/-jurisdiction) also needs: %s", strings.Join(missing, ", "))
180		}
181		subject, err := readSecret(cfg) // the subject token to exchange
182		if err != nil {
183			return nil, nil, err
184		}
185		creds := newJurisdictionCreds(httpc, cfg.tokenURL, cfg.jurisdiction, cfg.clientID, subject, "token")
186		ep, err := newEntireEndpoint(ctx, cfg, creds, httpc)
187		if err != nil {
188			return nil, nil, err
189		}
190		return creds, ep, nil
191	}
192	
193	// isGitHubDotCom reports whether remote points at github.com (so the abuse
194	// warning + sha1 constraint apply). Any other host — GHES, GitLab, Gitea — is
195	// just a generic forge.
196	func isGitHubDotCom(remote string) bool {
197		u, err := url.Parse(remote)
198		if err != nil {
199			return false
200		}
201		return strings.EqualFold(u.Hostname(), "github.com")
202	}
203	
204	// readSecret returns the credential secret from the most secure source
205	// available: -token-file (a file path, or "-" for stdin) if set, otherwise the
206	// ACCESS_TOKEN env var. A raw token on argv is intentionally unsupported — it
207	// would leak via ps(1) and shell history. The secret is the forge access token
208	// for a plain forge, or the subject token to exchange for Entire.
209	func readSecret(cfg *runConfig) (string, error) {
210		if cfg.tokenFile != "" {
211			var (
212				b   []byte
213				err error
214			)
215			if cfg.tokenFile == "-" {
216				b, err = io.ReadAll(os.Stdin)
217			} else {
218				b, err = os.ReadFile(cfg.tokenFile)
219			}
220			if err != nil {
221				return "", fmt.Errorf("read -token-file: %w", err)
222			}
223			if s := strings.TrimSpace(string(b)); s != "" {
224				return s, nil
225			}
226			return "", errors.New("-token-file is empty")
227		}
228		if t := os.Getenv("ACCESS_TOKEN"); t != "" {
229			return t, nil
230		}
231		return "", errors.New("no credential: pass -token-file <path|-> (recommended) or set ACCESS_TOKEN")
232	}
233	
234	func parseObjectFormat(s string) (formatcfg.ObjectFormat, error) {
235		switch s {
236		case "sha256":
237			return formatcfg.SHA256, nil
238		case "sha1", "auto", "": // generic doesn't probe; auto degrades to sha1
239			return formatcfg.SHA1, nil
240		default:
241			return "", fmt.Errorf("invalid -object-format %q (sha1|sha256|auto)", s)
242		}
243	}
244	
245	// runLevel runs a single concurrency level: spin up c agents for
246	// warmup+duration, then fold their samples into one result.
247	func runLevel(ctx context.Context, cfg *runConfig, creds credentialProvider, ep *endpoint, httpc *http.Client, c int) (levelResult, error) {
248		var clone *cloneConfig
249		var sess *sessionConfig
250		switch cfg.strategy {
251		case "clone":
252			clone = &cloneConfig{cloneDepth: cfg.cloneDepth, baseRef: cfg.baseRef}
253		case "session":
254			sess = &sessionConfig{
255				cloneConfig: cloneConfig{cloneDepth: cfg.cloneDepth, baseRef: cfg.baseRef},
256				commits:     cfg.sessionCommits,
257			}
258		}
259		agents := make([]*agent, c)
260		for i := range c {
261			repoPath := cfg.repos[0]
262			if cfg.strategy == "repo" {
263				repoPath = cfg.repos[i%len(cfg.repos)]
264			}
265			node := ep.nodes[i%len(ep.nodes)]
266			ref := destRef(cfg.branchPrefix, cfg.runID, c, i)
267			a, err := newAgent(i, repoPath, node, ref, ep.objFmt, &cfg.commit, creds, httpc, clone, sess)
268			if err != nil {
269				return levelResult{}, fmt.Errorf("new agent %d: %w", i, err)
270			}
271			agents[i] = a
272		}
273	
274		total := cfg.warmup + cfg.duration
275		lvlCtx, cancel := context.WithTimeout(ctx, total)
276		defer cancel()
277	
278		start := time.Now()
279		var wg sync.WaitGroup
280		for _, a := range agents {
281			wg.Add(1)
282			go func(a *agent) {
283				defer wg.Done()
284				a.run(lvlCtx, start)
285			}(a)
286		}
287		wg.Wait()
288	
289		var all []sample
290		for _, a := range agents {
291			all = append(all, a.samples...)
292		}
293		reposUsed := 1
294		if cfg.strategy == "repo" {
295			reposUsed = min(c, len(cfg.repos))
296		}
297		return summarize(all, c, cfg.strategy, reposUsed, len(ep.nodes), cfg.warmup, cfg.duration, cfg.commitDesc()), nil
298	}
