300	func newHTTPClient(insecure bool, maxConns int) *http.Client {
301		tr := &http.Transport{
302			Proxy:               http.ProxyFromEnvironment,
303			MaxIdleConns:        maxConns * 2,
304			MaxIdleConnsPerHost: maxConns,
305			MaxConnsPerHost:     0, // unbounded: don't queue pushes behind a conn cap
306			IdleConnTimeout:     90 * time.Second,
307		}
308		if insecure {
309			tr.TLSClientConfig = &tls.Config{InsecureSkipVerify: true} //nolint:gosec // load-test opt-in
310		}
311		return &http.Client{Transport: tr, Timeout: 120 * time.Second}
312	}
313	
314	func (c *runConfig) commitDesc() string {
315		return fmt.Sprintf("%d-%d x %dB", c.commit.filesMin, c.commit.filesMax, c.commit.fileSize)
316	}
