318	func parseFlags() (*runConfig, error) {
319		cfg := &runConfig{}
320		var reposCSV, pattern, concCSV string
321		var repoCount int
322	
323		flag.StringVar(&cfg.remote, "remote", "", "base URL of the forge, e.g. https://gitlab.com (repos are appended verbatim as <base>/<repo>); for Entire, the cluster base URL")
324		flag.StringVar(&cfg.tokenFile, "token-file", "", "path to a file holding the credential secret (Entire: the subject token); \"-\" reads stdin. Preferred over $ACCESS_TOKEN — keeps the secret off argv")
325		flag.StringVar(&cfg.user, "user", "", "basic-auth username for the credential (default x-access-token; token forges ignore it)")
326		flag.StringVar(&reposCSV, "repos", "", "comma-separated repo paths, appended to -remote verbatim (e.g. you/bench.git)")
327		flag.StringVar(&pattern, "repo-pattern", "", "repo path template; {n} is replaced by the index (1..N), used with -repo-count (e.g. you/bench-{n})")
328		flag.IntVar(&repoCount, "repo-count", 0, "number of repos for -repo-pattern (expands {n} = 1..N)")
329		flag.StringVar(&cfg.strategy, "strategy", "branch", "branch (one repo, per-agent branches) | repo (spread across repos) | clone (clone-only read loop) | session (clone+push loop per agent)")
330		flag.StringVar(&cfg.branchPrefix, "branch-prefix", "", "prefix prepended verbatim to branch names, before the run ID (e.g. bench/ → refs/heads/bench/fm...-c1-a0); empty keeps the default")
331		flag.StringVar(&concCSV, "concurrency", "1,8,32,128", "comma-separated writer counts to sweep")
332		flag.DurationVar(&cfg.duration, "duration", 60*time.Second, "measured window per concurrency level")
333		flag.DurationVar(&cfg.warmup, "warmup", 10*time.Second, "warm-up before measuring (excluded from stats)")
334		flag.IntVar(&cfg.commit.filesMin, "files-min", 1, "min changed files per commit")
335		flag.IntVar(&cfg.commit.filesMax, "files-max", 10, "max changed files per commit")
336		flag.IntVar(&cfg.commit.fileSize, "file-size", 2048, "bytes per changed file")
337		flag.StringVar(&cfg.objectFmt, "object-format", "auto", "auto | sha1 | sha256 (auto probes the entiredb advertisement; generic/github default sha1)")
338		flag.BoolVar(&cfg.insecure, "insecure", false, "skip TLS verification (dev/self-signed hosts)")
339		flag.StringVar(&cfg.out, "out", "", "write JSON results here (default: results/forgemark-<id>.json)")
340		flag.IntVar(&cfg.sessionCommits, "session-commits", 5, "session strategy: commit+push checkpoints per cloned session")
341		flag.IntVar(&cfg.cloneDepth, "clone-depth", 1, "clone/session strategy: shallow clone depth (1=tip; 0=full history)")
342		flag.StringVar(&cfg.baseRef, "base-ref", "", "clone/session strategy: branch to clone — bare name (main) or full ref (refs/heads/main); default: remote default branch")
343	
344		// entiredb: presence of -token-url/-jurisdiction selects the entiredb path.
345		flag.StringVar(&cfg.tokenURL, "token-url", "", "entiredb: core /oauth/token endpoint, e.g. https://<region>.auth.example.com/oauth/token (selects entiredb)")
346		flag.StringVar(&cfg.jurisdiction, "jurisdiction", "", "entiredb: jurisdiction audience host (bare origin), e.g. https://<region>.example.com (selects entiredb)")
347		flag.StringVar(&cfg.clientID, "client-id", "entire-cli", "entiredb: public OAuth client id for the exchange")
348		flag.Parse()
349	
350		repos, err := expandRepos(reposCSV, pattern, repoCount)
351		if err != nil {
352			return nil, err
353		}
354		cfg.repos = repos
355		if cfg.strategy != "branch" && cfg.strategy != "repo" && cfg.strategy != "clone" && cfg.strategy != "session" {
356			return nil, fmt.Errorf("invalid -strategy %q (branch|repo|clone|session)", cfg.strategy)
357		}
358		if cfg.strategy == "repo" && len(cfg.repos) < 2 {
359			return nil, errors.New("strategy=repo needs >= 2 repos")
360		}
361		if cfg.strategy == "session" && cfg.sessionCommits < 1 {
362			return nil, errors.New("-session-commits must be >= 1")
363		}
364		for _, p := range splitCSV(concCSV) {
365			n, err := strconv.Atoi(p)
366			if err != nil || n < 1 {
367				return nil, fmt.Errorf("invalid concurrency %q", p)
368			}
369			cfg.concurrency = append(cfg.concurrency, n)
370		}
371		if len(cfg.concurrency) == 0 {
372			return nil, errors.New("no concurrency levels")
373		}
374		if cfg.strategy != "clone" {
375			if cfg.commit.filesMin < 1 {
376				return nil, errors.New("-files-min must be >= 1 (a commit needs a change to push)")
377			}
378			if cfg.commit.filesMax < cfg.commit.filesMin {
379				return nil, errors.New("-files-max < -files-min")
380			}
381			if cfg.commit.fileSize < 1 {
382				return nil, errors.New("-file-size must be >= 1 (empty blobs reproduce → ErrEmptyCommit)")
383			}
384		}
385		cfg.runID = "fm" + strconv.FormatInt(time.Now().Unix(), 36)
386		// Validate the assembled ref, not the prefix alone: validity is context-dependent
387		// (a trailing "/" or bare word is fine mid-ref, invalid standalone). c/a are arbitrary —
388		// only the prefix can invalidate it — so this one parse-time check covers the whole sweep.
389		if err := plumbing.ReferenceName(destRef(cfg.branchPrefix, cfg.runID, 1, 0)).Validate(); err != nil {
390			return nil, fmt.Errorf("invalid -branch-prefix %q: %w", cfg.branchPrefix, err)
391		}
392		return cfg, nil
393	}
394	
395	// destRef builds an agent's destination branch ref, prepending branchPrefix
396	// verbatim before the run ID. Empty prefix reproduces the default name.
397	func destRef(branchPrefix, runID string, c, i int) string {
398		return fmt.Sprintf("refs/heads/%s%s-c%d-a%d", branchPrefix, runID, c, i)
399	}
400	
401	// expandRepos builds the target repo list from the mutually-exclusive
402	// -repos / -repo-pattern flags. Paths are used verbatim downstream (the
403	// endpoint appends them to the node with no rewriting), so this only validates
404	// and expands {n}; it never rewrites the path shape.
405	func expandRepos(reposCSV, pattern string, count int) ([]string, error) {
406		repos := splitCSV(reposCSV)
407		switch {
408		case len(repos) > 0 && pattern != "":
409			return nil, errors.New("pass -repos or -repo-pattern, not both")
410		case len(repos) > 0:
411			if count > 0 {
412				return nil, errors.New("-repo-count applies to -repo-pattern, not -repos")
413			}
414			return repos, nil
415		case pattern != "":
416			if count <= 0 {
417				return nil, errors.New("-repo-pattern requires -repo-count > 0")
418			}
419			if !strings.Contains(pattern, "{n}") {
420				return nil, errors.New("-repo-pattern must contain the {n} index placeholder (e.g. you/bench-{n})")
421			}
422			for i := 1; i <= count; i++ {
423				repos = append(repos, strings.ReplaceAll(pattern, "{n}", strconv.Itoa(i)))
424			}
425			return repos, nil
426		case count > 0:
427			return nil, errors.New("-repo-count requires -repo-pattern")
428		default:
429			return nil, errors.New("no repos: pass -repos or -repo-pattern + -repo-count")
430		}
431	}
