433	func printRow(r levelResult) {
434		if r.Strategy == "clone" {
435			fmt.Printf("  c=%-4d clone_ok=%-6d clone/s=%-8.1f p50=%-7.1f p95=%-8.1f p99=%-8.1f max=%-8.1f clone_err=%d\n",
436				r.Concurrency, r.OK, r.OpsPerSec, r.P50ms, r.P95ms, r.P99ms, r.Maxms, r.OtherErrors)
437			return
438		}
439		fmt.Printf("  c=%-4d push_ok=%-6d push/s=%-8.1f p50=%-7.1f p95=%-8.1f p99=%-8.1f max=%-8.1f cas=%d err=%d\n",
440			r.Concurrency, r.OK, r.OpsPerSec, r.P50ms, r.P95ms, r.P99ms, r.Maxms, r.CASFailures, r.OtherErrors)
441		if r.Clones > 0 {
442			fmt.Printf("        clones=%-5d clone_ok=%-5d clone_p50=%-7.1f clone_p95=%-8.1f clone_p99=%-8.1f clone_err=%d\n",
443				r.Clones, r.CloneOK, r.CloneP50ms, r.CloneP95ms, r.CloneP99ms, r.CloneErrors)
444		}
445	}
