447	func writeResults(cfg *runConfig, ep *endpoint, results []levelResult) error {
448		out := cfg.out
449		if out == "" {
450			if err := os.MkdirAll("results", 0o750); err != nil {
451				return fmt.Errorf("mkdir results: %w", err)
452			}
453			out = fmt.Sprintf("results/forgemark-%s.json", cfg.runID)
454		}
455		doc := map[string]any{
456			"run_id":     cfg.runID,
457			"target":     ep.label,
458			"strategy":   cfg.strategy,
459			"duration":   cfg.duration.String(),
460			"warmup":     cfg.warmup.String(),
461			"repo_count": len(cfg.repos),
462			"commit":     cfg.commitDesc(),
463			"levels":     results,
464		}
465		b, err := json.MarshalIndent(doc, "", "  ")
466		if err != nil {
467			return fmt.Errorf("marshal results: %w", err)
468		}
469		if err := os.WriteFile(out, b, 0o600); err != nil {
470			return fmt.Errorf("write results: %w", err)
471		}
472		fmt.Printf("\nwrote %s\n", out)
473		return nil
474	}
