16	func TestExpandRepos(t *testing.T) {
17		tests := []struct {
18			name     string
19			reposCSV string
20			pattern  string
21			count    int
22			want     []string
23			wantErr  bool
24		}{
25			{name: "repos passthrough", reposCSV: "a/b,c/d", want: []string{"a/b", "c/d"}},
26			{name: "pattern expands 1..N", pattern: "org/bench-{n}", count: 3,
27				want: []string{"org/bench-1", "org/bench-2", "org/bench-3"}},
28			{name: "pattern repeats {n}", pattern: "grp-{n}/bench-{n}", count: 2,
29				want: []string{"grp-1/bench-1", "grp-2/bench-2"}},
30			{name: "pattern keeps verbatim suffix", pattern: "you/bench-{n}.git", count: 2,
31				want: []string{"you/bench-1.git", "you/bench-2.git"}},
32			{name: "missing {n}", pattern: "bench-", count: 3, wantErr: true},
33			{name: "pattern without count", pattern: "bench-{n}", count: 0, wantErr: true},
34			{name: "count without pattern", count: 3, wantErr: true},
35			{name: "repos plus count", reposCSV: "a/b", count: 3, wantErr: true},
36			{name: "both repos and pattern", reposCSV: "a/b", pattern: "c-{n}", count: 2, wantErr: true},
37			{name: "neither", wantErr: true},
38		}
39		for _, tt := range tests {
40			t.Run(tt.name, func(t *testing.T) {
41				got, err := expandRepos(tt.reposCSV, tt.pattern, tt.count)
42				if (err != nil) != tt.wantErr {
43					t.Fatalf("expandRepos(%q,%q,%d) err = %v, wantErr %v", tt.reposCSV, tt.pattern, tt.count, err, tt.wantErr)
44				}
45				if tt.wantErr {
46					return
47				}
48				if !reflect.DeepEqual(got, tt.want) {
49					t.Fatalf("expandRepos(%q,%q,%d) = %v, want %v", tt.reposCSV, tt.pattern, tt.count, got, tt.want)
50				}
51			})
52		}
53	}
