// Package bench is the forgemark benchmark engine: it drives real git
// push/clone operations against one target forge and reports per-level
// results. The CLI (cmd/forgemark) and the web server (internal/server) are
// both thin frontends over Runner.
package bench

import (
	"errors"
	"fmt"
	"net/url"
	"strconv"
	"strings"
	"time"

	"github.com/go-git/go-git/v6/plumbing"
)

// Target is one forge to benchmark: where to connect and how to authenticate.
// Supplying TokenURL or Jurisdiction selects the entiredb path (jurisdiction
// token exchange + node discovery); they mean nothing to any other forge, so
// their presence is the signal — no separate target-kind field.
type Target struct {
	Name      string   // display label; empty defaults to the remote base URL
	Remote    string   // base URL of the forge, e.g. https://gitlab.com
	Repos     []string // repo paths appended to Remote verbatim
	User      string   // basic-auth username (default x-access-token; token forges ignore it)
	Secret    string   // credential secret (forge token, or the entiredb subject token). Never serialized.
	Insecure  bool     // skip TLS verification
	ObjectFmt string   // "auto" | "sha1" | "sha256"

	// entiredb
	TokenURL     string // core /oauth/token endpoint (selects entiredb)
	Jurisdiction string // jurisdiction audience host, bare origin (selects entiredb)
	ClientID     string // public OAuth client id; empty defaults to entire-cli
}

// Workload is the target-independent shape of a run: strategy, sweep, and
// commit content. One Workload is shared by every target of a comparison run.
type Workload struct {
	RunID        string
	Strategy     string // branch | repo | clone | session
	BranchPrefix string
	Concurrency  []int
	Duration     time.Duration
	Warmup       time.Duration
	Commit       CommitConfig

	// session/clone strategies
	SessionCommits int
	CloneDepth     int
	BaseRef        string
}

// Validate applies the target-independent checks that parseFlags used to do,
// so the server rejects a bad workload with the same errors the CLI reports.
func (w Workload) Validate() error {
	switch w.Strategy {
	case "branch", "repo", "clone", "session":
	default:
		return fmt.Errorf("invalid -strategy %q (branch|repo|clone|session)", w.Strategy)
	}
	if w.Strategy == "session" && w.SessionCommits < 1 {
		return errors.New("-session-commits must be >= 1")
	}
	if len(w.Concurrency) == 0 {
		return errors.New("no concurrency levels")
	}
	for _, n := range w.Concurrency {
		if n < 1 {
			return fmt.Errorf("invalid concurrency %d", n)
		}
	}
	if w.Duration <= 0 {
		return errors.New("-duration must be > 0")
	}
	if w.Warmup < 0 {
		return errors.New("-warmup must be >= 0")
	}
	if w.Strategy != "clone" {
		if w.Commit.FilesMin < 1 {
			return errors.New("-files-min must be >= 1 (a commit needs a change to push)")
		}
		if w.Commit.FilesMax < w.Commit.FilesMin {
			return errors.New("-files-max < -files-min")
		}
		if w.Commit.FileSize < 1 {
			return errors.New("-file-size must be >= 1 (empty blobs reproduce → ErrEmptyCommit)")
		}
	}
	// Validate the assembled ref, not the prefix alone: validity is context-dependent
	// (a trailing "/" or bare word is fine mid-ref, invalid standalone). c/a are arbitrary —
	// only the prefix can invalidate it — so this one parse-time check covers the whole sweep.
	runID := w.RunID
	if runID == "" {
		runID = "fmX"
	}
	if err := plumbing.ReferenceName(DestRef(w.BranchPrefix, runID, 1, 0)).Validate(); err != nil {
		return fmt.Errorf("invalid -branch-prefix %q: %w", w.BranchPrefix, err)
	}
	return nil
}

// CommitDesc describes the commit content shape, e.g. "1-10 x 2048B".
func (w Workload) CommitDesc() string {
	return fmt.Sprintf("%d-%d x %dB", w.Commit.FilesMin, w.Commit.FilesMax, w.Commit.FileSize)
}

// NewRunID returns a fresh run identifier. Nanosecond resolution so two runs
// started back-to-back (a server restarting a sweep) can't collide.
func NewRunID() string {
	return "fm" + strconv.FormatInt(time.Now().UnixNano(), 36)
}

// DestRef builds an agent's destination branch ref, prepending branchPrefix
// verbatim before the run ID. Empty prefix reproduces the default name.
func DestRef(branchPrefix, runID string, c, i int) string {
	return fmt.Sprintf("refs/heads/%s%s-c%d-a%d", branchPrefix, runID, c, i)
}

// IsGitHubDotCom reports whether remote points at github.com (so the abuse
// warning + sha1 constraint apply). Any other host — GHES, GitLab, Gitea — is
// just a generic forge.
func IsGitHubDotCom(remote string) bool {
	u, err := url.Parse(remote)
	if err != nil {
		return false
	}
	return strings.EqualFold(u.Hostname(), "github.com")
}

package bench

import (
	"context"
	"crypto/tls"
	"errors"
	"fmt"
	"net/http"
	"slices"
	"sync"
	"time"

	formatcfg "github.com/go-git/go-git/v6/plumbing/format/config"
)

// Runner drives one target through concurrency levels of one workload. The
// caller owns the sweep loop: it calls RunLevel once per level, so level
// lifecycle (start/end, the returned LevelResult) is the caller's to observe —
// the engine only reports per-operation samples, via the optional Sink.
type Runner struct {
	target Target
	w      Workload
	creds  credentialProvider
	ep     *endpoint
	httpc  *http.Client
	sink   Sink
}

// NewRunner resolves a target (credentials + endpoint; for entiredb this
// probes the cluster) and validates the workload against it. sink may be nil.
func NewRunner(ctx context.Context, t Target, w Workload, sink Sink) (*Runner, error) {
	if err := w.Validate(); err != nil {
		return nil, err
	}
	if len(t.Repos) == 0 {
		return nil, errors.New("no repos: pass -repos or -repo-pattern + -repo-count")
	}
	if w.Strategy == "repo" && len(t.Repos) < 2 {
		return nil, errors.New("strategy=repo needs >= 2 repos")
	}
	if t.Secret == "" {
		return nil, errors.New("no credential secret provided")
	}
	httpc := newHTTPClient(t.Insecure, slices.Max(w.Concurrency)+8)

	var (
		creds credentialProvider
		ep    *endpoint
		err   error
	)
	if t.TokenURL != "" || t.Jurisdiction != "" {
		creds, ep, err = setupEntiredb(ctx, t, httpc)
	} else {
		creds, ep, err = setupGeneric(t)
	}
	if err != nil {
		return nil, err
	}
	return &Runner{target: t, w: w, creds: creds, ep: ep, httpc: httpc, sink: sink}, nil
}

// Label is the resolved endpoint label (the remote base URL), for banners and
// results.
func (r *Runner) Label() string { return r.ep.label }

// Nodes is how many push destinations the endpoint fans out across (1 for any
// plain forge; the discovered replica count for entiredb).
func (r *Runner) Nodes() int { return len(r.ep.nodes) }

// ObjectFormat is the resolved wire object format ("sha1" or "sha256").
func (r *Runner) ObjectFormat() string { return string(r.ep.objFmt) }

// RunLevel runs a single concurrency level: spin up c agents for
// warmup+duration, then fold their samples into one result. It blocks for the
// full level window (or until ctx is cancelled).
func (r *Runner) RunLevel(ctx context.Context, c int) (LevelResult, error) {
	var clone *cloneConfig
	var sess *sessionConfig
	switch r.w.Strategy {
	case "clone":
		clone = &cloneConfig{cloneDepth: r.w.CloneDepth, baseRef: r.w.BaseRef}
	case "session":
		sess = &sessionConfig{
			cloneConfig: cloneConfig{cloneDepth: r.w.CloneDepth, baseRef: r.w.BaseRef},
			commits:     r.w.SessionCommits,
		}
	}
	agents := make([]*agent, c)
	for i := range c {
		repoPath := r.target.Repos[0]
		if r.w.Strategy == "repo" {
			repoPath = r.target.Repos[i%len(r.target.Repos)]
		}
		node := r.ep.nodes[i%len(r.ep.nodes)]
		ref := DestRef(r.w.BranchPrefix, r.w.RunID, c, i)
		a, err := newAgent(i, repoPath, node, ref, r.ep.objFmt, &r.w.Commit, r.creds, r.httpc, clone, sess)
		if err != nil {
			return LevelResult{}, fmt.Errorf("new agent %d: %w", i, err)
		}
		agents[i] = a
	}

	total := r.w.Warmup + r.w.Duration
	lvlCtx, cancel := context.WithTimeout(ctx, total)
	defer cancel()

	start := time.Now()
	var wg sync.WaitGroup
	for _, a := range agents {
		wg.Add(1)
		go func(a *agent) {
			defer wg.Done()
			a.run(lvlCtx, start)
		}(a)
	}
	wg.Wait()

	var all []sample
	for _, a := range agents {
		all = append(all, a.samples...)
	}
	reposUsed := 1
	if r.w.Strategy == "repo" {
		reposUsed = min(c, len(r.target.Repos))
	}
	return summarize(all, c, r.w.Strategy, reposUsed, len(r.ep.nodes), r.w.Warmup, r.w.Duration, r.w.CommitDesc()), nil
}

func setupGeneric(t Target) (credentialProvider, *endpoint, error) {
	if t.Remote == "" {
		return nil, nil, errors.New("-remote required (e.g. https://gitlab.com); for entiredb also pass -token-url and -jurisdiction")
	}
	if IsGitHubDotCom(t.Remote) && t.ObjectFmt == "sha256" {
		return nil, nil, errors.New("github.com is sha1; drop -object-format sha256")
	}
	objFmt, err := parseObjectFormat(t.ObjectFmt)
	if err != nil {
		return nil, nil, err
	}
	user := t.User
	if user == "" {
		user = "x-access-token" // token forges ignore the username; the token is the password
	}
	return staticCreds{username: user, password: t.Secret}, newGenericEndpoint(t.Remote, objFmt), nil
}

func setupEntiredb(ctx context.Context, t Target, httpc *http.Client) (credentialProvider, *endpoint, error) {
	var missing []string
	if t.Remote == "" {
		missing = append(missing, "-remote (cluster base URL)")
	}
	if t.TokenURL == "" {
		missing = append(missing, "-token-url")
	}
	if t.Jurisdiction == "" {
		missing = append(missing, "-jurisdiction")
	}
	if len(missing) > 0 {
		return nil, nil, fmt.Errorf("entire target (selected by -token-url/-jurisdiction) also needs: %s", strings.Join(missing, ", "))
	}
	clientID := t.ClientID
	if clientID == "" {
		clientID = "entire-cli"
	}
	creds := newJurisdictionCreds(httpc, t.TokenURL, t.Jurisdiction, clientID, t.Secret, "token")
	ep, err := newEntireEndpoint(ctx, t.Remote, t.ObjectFmt, t.Repos[0], creds, httpc)
	if err != nil {
		return nil, nil, err
	}
	return creds, ep, nil
}

func parseObjectFormat(s string) (formatcfg.ObjectFormat, error) {
	switch s {
	case "sha256":
		return formatcfg.SHA256, nil
	case "sha1", "auto", "": // generic doesn't probe; auto degrades to sha1
		return formatcfg.SHA1, nil
	default:
		return "", fmt.Errorf("invalid -object-format %q (sha1|sha256|auto)", s)
	}
}

func newHTTPClient(insecure bool, maxConns int) *http.Client {
	tr := &http.Transport{
		Proxy:               http.ProxyFromEnvironment,
		MaxIdleConns:        maxConns * 2,
		MaxIdleConnsPerHost: maxConns,
		MaxConnsPerHost:     0, // unbounded: don't queue pushes behind a conn cap
		IdleConnTimeout:     90 * time.Second,
	}
	if insecure {
		tr.TLSClientConfig = &tls.Config{InsecureSkipVerify: true} //nolint:gosec // load-test opt-in
	}
	return &http.Client{Transport: tr, Timeout: 120 * time.Second}
}

