// sample is one recorded operation. offset is measured from the start of the
// concurrency level so warm-up samples can be dropped post-hoc.
type sample struct {
	offset time.Duration
	dur    time.Duration
	res    Outcome
	op     OpKind
	msg    string // raw error text, retained only when res == OutcomeErr
}

// Sample is the exported view of one recorded operation, delivered live to a
// Sink as the agent records it.
type Sample struct {
	Offset time.Duration // measured from level start; warm-up samples included
	Dur    time.Duration
	Res    Outcome
	Op     OpKind
	Msg    string // raw error text, only when Res == OutcomeErr
}

// Sink observes every sample live, warm-up included. OnSample is called
// concurrently from up to `concurrency` agent goroutines mid-measurement, so
// it must be cheap and non-blocking (a mutex-protected aggregator is fine; a
// slow sink would perturb the numbers being measured). A nil Sink disables
// observation — the CLI path.
type Sink interface {
	OnSample(s Sample)
}

	cfg   *CommitConfig
	creds credentialProvider
	httpc *http.Client
	clone *cloneConfig   // non-nil → "clone" strategy (clone-only loop)
	sess  *sessionConfig // non-nil → "session" strategy (clone+push loop)
	sink  Sink           // optional live observer; nil on the CLI path

	repo    *git.Repository
	samples []sample
}

// record appends a sample to the agent's authoritative post-hoc log and, when
// a sink is attached, forwards it live. Every sample the agent takes goes
// through here.
func (a *agent) record(s sample) {
	a.samples = append(a.samples, s)
	if a.sink != nil {
		a.sink.OnSample(Sample{Offset: s.offset, Dur: s.dur, Res: s.res, Op: s.op, Msg: s.msg})
	}
}

