package server

import (
	"sort"
	"sync"
	"time"

	"github.com/entireio/forgemark/internal/bench"
)

// windowSecs is the rolling-percentile window: latency percentiles in a bucket
// event are computed over the OK samples of the last windowSecs seconds, so a
// single quiet second doesn't blank the lines while spikes still show quickly.
const windowSecs = 10

// collector is the live aggregator for one target of one run. It implements
// bench.Sink: agents call OnSample concurrently mid-measurement, so it does
// only counter increments and one append under its mutex. Once per second the
// run's ticker calls snapshot, which swaps the current bucket out and computes
// rolling percentiles (an exact sort over the window — a few thousand floats,
// ~100µs, nothing at benchmark sample rates).
type collector struct {
	mu       sync.Mutex
	cur      bucket
	ring     [windowSecs][]float64 // push OK latencies, one slot per elapsed second
	cloneRing [windowSecs][]float64
	pos      int
}

// bucket accumulates one second of samples.
type bucket struct {
	ops, ok, cas, errs        int
	clones, cloneOK, cloneErr int
	lat                       []float64 // OK push latencies (ms)
	cloneLat                  []float64 // OK clone latencies (ms)
}

// BucketStats is one target's slice of a per-second bucket event. Push and
// clone ops are reported separately, mirroring LevelResult; the UI picks the
// primary series from the workload strategy.
type BucketStats struct {
	Ops int `json:"ops"`
	OK  int `json:"ok"`
	CAS int `json:"cas"`
	Err int `json:"err"`
	// Rolling percentiles over the last windowSecs seconds of OK pushes.
	P50 float64 `json:"p50_ms"`
	P95 float64 `json:"p95_ms"`
	P99 float64 `json:"p99_ms"`

	Clones   int     `json:"clones,omitempty"`
	CloneOK  int     `json:"clone_ok,omitempty"`
	CloneErr int     `json:"clone_err,omitempty"`
	CloneP50 float64 `json:"clone_p50_ms,omitempty"`
	CloneP95 float64 `json:"clone_p95_ms,omitempty"`
	CloneP99 float64 `json:"clone_p99_ms,omitempty"`
}

func (c *collector) OnSample(s bench.Sample) {
	ms := float64(s.Dur) / float64(time.Millisecond)
	c.mu.Lock()
	defer c.mu.Unlock()
	if s.Op == bench.OpClone {
		c.cur.clones++
		switch s.Res {
		case bench.OutcomeOK:
			c.cur.cloneOK++
			c.cur.cloneLat = append(c.cur.cloneLat, ms)
		default:
			c.cur.cloneErr++
		}
		return
	}
	c.cur.ops++
	switch s.Res {
	case bench.OutcomeOK:
		c.cur.ok++
		c.cur.lat = append(c.cur.lat, ms)
	case bench.OutcomeCAS:
		c.cur.cas++
	default:
		c.cur.errs++
	}
}

// snapshot closes out the current second: it returns its counters and the
// rolling percentiles over the updated window.
func (c *collector) snapshot() BucketStats {
	c.mu.Lock()
	b := c.cur
	c.cur = bucket{}
	c.ring[c.pos] = b.lat
	c.cloneRing[c.pos] = b.cloneLat
	c.pos = (c.pos + 1) % windowSecs
	var lat, cloneLat []float64
	for i := range c.ring {
		lat = append(lat, c.ring[i]...)
		cloneLat = append(cloneLat, c.cloneRing[i]...)
	}
	c.mu.Unlock()

	st := BucketStats{
		Ops: b.ops, OK: b.ok, CAS: b.cas, Err: b.errs,
		Clones: b.clones, CloneOK: b.cloneOK, CloneErr: b.cloneErr,
	}
	if len(lat) > 0 {
		sort.Float64s(lat)
		st.P50 = bench.Percentile(lat, 50)
		st.P95 = bench.Percentile(lat, 95)
		st.P99 = bench.Percentile(lat, 99)
	}
	if len(cloneLat) > 0 {
		sort.Float64s(cloneLat)
		st.CloneP50 = bench.Percentile(cloneLat, 50)
		st.CloneP95 = bench.Percentile(cloneLat, 95)
		st.CloneP99 = bench.Percentile(cloneLat, 99)
	}
	return st
}

// reset clears the bucket and the rolling window. Called at each level start
// so percentiles never bleed across concurrency levels.
func (c *collector) reset() {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.cur = bucket{}
	c.ring = [windowSecs][]float64{}
	c.cloneRing = [windowSecs][]float64{}
	c.pos = 0
}

package server

import (
	"encoding/json"
	"fmt"
	"net/http"
	"strconv"
	"sync"
	"time"
)

// maxBufferedEvents caps a run's replayable event log. At ~1 bucket event per
// second this is over a day of run time — a backstop, not a working limit.
const maxBufferedEvents = 100_000

// event is one serialized SSE frame: a 1-based sequence number (the SSE id,
// which browsers echo back as Last-Event-ID on reconnect), a type, and its
// marshaled JSON payload.
type event struct {
	seq  int64
	name string
	data []byte
}

// eventLog is a run's append-only event history plus live fanout. Every event
// is retained (bounded by maxBufferedEvents), so a subscriber at any point —
// first open, late join, browser reconnect — is handled the same way: replay
// everything after its Last-Event-ID, then stream. That makes dropping a slow
// subscriber lossless: it reconnects and replays what it missed.
type eventLog struct {
	mu     sync.Mutex
	events []event
	subs   map[chan event]struct{}
	closed bool
}

func newEventLog() *eventLog {
	return &eventLog{subs: make(map[chan event]struct{})}
}

// emit marshals v, appends the event, and fans it out. A subscriber whose
// buffer is full is dropped (its channel closed) rather than blocking the
// coordinator; the SSE handler ends that response and the browser reconnects
// into a replay.
func (l *eventLog) emit(name string, v any) {
	data, err := json.Marshal(v)
	if err != nil {
		// A marshal failure is a programming error in an event payload; surface
		// it in-band rather than silently dropping the event.
		data = fmt.Appendf(nil, `{"error":"marshal: %s"}`, err)
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	if l.closed || len(l.events) >= maxBufferedEvents {
		return
	}
	e := event{seq: int64(len(l.events)) + 1, name: name, data: data}
	l.events = append(l.events, e)
	for ch := range l.subs {
		select {
		case ch <- e:
		default:
			delete(l.subs, ch)
			close(ch)
		}
	}
}

// subscribe returns the replay of every event after seq `after`, plus a live
// channel (nil if the log is closed — the replay then already ends in the
// terminal event) and a cancel func.
func (l *eventLog) subscribe(after int64) ([]event, chan event, func()) {
	l.mu.Lock()
	defer l.mu.Unlock()
	var replay []event
	if after < int64(len(l.events)) {
		replay = append(replay, l.events[after:]...)
	}
	if l.closed {
		return replay, nil, func() {}
	}
	ch := make(chan event, 256)
	l.subs[ch] = struct{}{}
	cancel := func() {
		l.mu.Lock()
		defer l.mu.Unlock()
		if _, ok := l.subs[ch]; ok {
			delete(l.subs, ch)
			close(ch)
		}
	}
	return replay, ch, cancel
}

// close ends the log after the terminal event has been emitted: live
// subscribers are closed out (their replay already delivered everything) and
// future subscribers get replay-only.
func (l *eventLog) close() {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.closed = true
	for ch := range l.subs {
		delete(l.subs, ch)
		close(ch)
	}
}

// serveSSE streams an eventLog as a Server-Sent-Events response: replay from
// the client's Last-Event-ID (or 0), then live events, with a comment
// heartbeat so proxies and the browser keep the connection alive.
func serveSSE(w http.ResponseWriter, r *http.Request, l *eventLog) {
	fl, ok := w.(http.Flusher)
	if !ok {
		http.Error(w, "streaming unsupported", http.StatusInternalServerError)
		return
	}
	var after int64
	if v := r.Header.Get("Last-Event-ID"); v != "" {
		after, _ = strconv.ParseInt(v, 10, 64)
	}

	w.Header().Set("Content-Type", "text/event-stream")
	w.Header().Set("Cache-Control", "no-cache")
	w.Header().Set("X-Accel-Buffering", "no")
	w.WriteHeader(http.StatusOK)

	replay, ch, cancel := l.subscribe(after)
	defer cancel()
	for _, e := range replay {
		writeSSE(w, e)
	}
	fl.Flush()
	if ch == nil {
		return // run already finished; the replay ended in run_done
	}

	heartbeat := time.NewTicker(15 * time.Second)
	defer heartbeat.Stop()
	for {
		select {
		case e, ok := <-ch:
			if !ok {
				return // log closed (run finished) or we were dropped as slow
			}
			writeSSE(w, e)
			fl.Flush()
		case <-heartbeat.C:
			fmt.Fprint(w, ": ping\n\n")
			fl.Flush()
		case <-r.Context().Done():
			return
		}
	}
}

func writeSSE(w http.ResponseWriter, e event) {
	fmt.Fprintf(w, "id: %d\nevent: %s\ndata: %s\n\n", e.seq, e.name, e.data)
}

package server

import (
	"context"
	"errors"
	"fmt"
	"net/url"
	"slices"
	"strconv"
	"sync"
	"time"

	"github.com/entireio/forgemark/internal/bench"
)

// maxTargets bounds one comparison run. Eight matches the UI's fixed target
// palette, and more than eight concurrent load generators from one laptop
// would perturb each other anyway.
const maxTargets = 8

// keepFinishedRuns is how many completed runs stay resident (with their full
// event logs) for the UI session; older ones live on only as result docs.
const keepFinishedRuns = 20

// levelRunner is what the coordinator drives, one per target: bench.Runner for
// a real forge, demoRunner for the synthetic offline target.
type levelRunner interface {
	Label() string
	Nodes() int
	ObjectFormat() string
	RunLevel(ctx context.Context, concurrency int) (bench.LevelResult, error)
}

// WorkloadSpec is the wire shape of a workload. Zero fields take the CLI's
// flag defaults (see withDefaults), so a minimal curl body works.
type WorkloadSpec struct {
	Strategy       string  `json:"strategy"`
	Concurrency    []int   `json:"concurrency"`
	DurationSec    float64 `json:"duration_sec"`
	WarmupSec      float64 `json:"warmup_sec"`
	FilesMin       int     `json:"files_min"`
	FilesMax       int     `json:"files_max"`
	FileSize       int     `json:"file_size"`
	BranchPrefix   string  `json:"branch_prefix"`
	SessionCommits int     `json:"session_commits"`
	CloneDepth     int     `json:"clone_depth"`
	BaseRef        string  `json:"base_ref"`
}

// withDefaults fills zero fields with the CLI flag defaults, and warmup with
// -1 sentinel handling: JSON can't distinguish absent from 0, and 0 is a valid
// warmup, so WarmupSec < 0 means "default 10s" and 0 means none.
func (ws WorkloadSpec) withDefaults() WorkloadSpec {
	if ws.Strategy == "" {
		ws.Strategy = "branch"
	}
	if len(ws.Concurrency) == 0 {
		ws.Concurrency = []int{1, 8, 32, 128}
	}
	if ws.DurationSec == 0 {
		ws.DurationSec = 60
	}
	if ws.WarmupSec < 0 {
		ws.WarmupSec = 10
	}
	if ws.FilesMin == 0 {
		ws.FilesMin = 1
	}
	if ws.FilesMax == 0 {
		ws.FilesMax = 10
	}
	if ws.FileSize == 0 {
		ws.FileSize = 2048
	}
	if ws.SessionCommits == 0 {
		ws.SessionCommits = 5
	}
	if ws.CloneDepth == 0 && ws.Strategy != "clone" && ws.Strategy != "session" {
		ws.CloneDepth = 1
	}
	if ws.CloneDepth == 0 {
		ws.CloneDepth = 1
	}
	return ws
}

func (ws WorkloadSpec) toWorkload(runID string) bench.Workload {
	return bench.Workload{
		RunID:          runID,
		Strategy:       ws.Strategy,
		BranchPrefix:   ws.BranchPrefix,
		Concurrency:    ws.Concurrency,
		Duration:       time.Duration(ws.DurationSec * float64(time.Second)),
		Warmup:         time.Duration(ws.WarmupSec * float64(time.Second)),
		Commit:         bench.CommitConfig{FilesMin: ws.FilesMin, FilesMax: ws.FilesMax, FileSize: ws.FileSize},
		SessionCommits: ws.SessionCommits,
		CloneDepth:     ws.CloneDepth,
		BaseRef:        ws.BaseRef,
	}
}

// TargetSpec is the wire shape of one target as POSTed. Secret exists ONLY
// here: it is consumed into the bench.Target and never stored on the run, so
// no status/list/event payload can leak it.
type TargetSpec struct {
	Name         string   `json:"name"`
	Remote       string   `json:"remote"`
	Repos        []string `json:"repos"`
	User         string   `json:"user"`
	Secret       string   `json:"secret"`
	Insecure     bool     `json:"insecure"`
	ObjectFormat string   `json:"object_format"`
	TokenURL     string   `json:"token_url"`
	Jurisdiction string   `json:"jurisdiction"`
	ClientID     string   `json:"client_id"`
}

func (ts TargetSpec) toTarget() bench.Target {
	return bench.Target{
		Name: ts.Name, Remote: ts.Remote, Repos: ts.Repos, User: ts.User,
		Secret: ts.Secret, Insecure: ts.Insecure, ObjectFmt: ts.ObjectFormat,
		TokenURL: ts.TokenURL, Jurisdiction: ts.Jurisdiction, ClientID: ts.ClientID,
	}
}

// TargetInfo is the redacted, stable identity of a target within a run.
type TargetInfo struct {
	ID     int    `json:"id"`
	Name   string `json:"name"`
	Remote string `json:"remote"`
}

type startRequest struct {
	ConfirmAuthorized bool         `json:"confirm_authorized"`
	Workload          WorkloadSpec `json:"workload"`
	Targets           []TargetSpec `json:"targets"`
}

// targetState is one target's live state inside a run. dead/fatalErr/results
// are guarded by the run's mutex; the collector has its own.
type targetState struct {
	id     int
	name   string
	spec   bench.Target // Secret is zeroed as soon as the runner is built
	runner levelRunner
	col    *collector

	label    string
	dead     bool
	fatalErr string
	results  []bench.LevelResult
}

// Run is one comparison run: N targets driven through one workload with
// level-aligned starts.
type Run struct {
	ID        string
	StartedAt time.Time
	log       *eventLog
	ctx       context.Context
	cancel    context.CancelFunc

	workload WorkloadSpec // normalized, as accepted
	bw       bench.Workload

	mu          sync.Mutex
	state       string // starting | running | done | cancelled | failed
	targets     []*targetState
	levelIdx    int
	levelConc   int
	resultsFile string
}

var errRunActive = errors.New("a benchmark run is already active; cancel it or wait for it to finish")

// RunManager owns every run of a server session and enforces the
// one-active-run-at-a-time rule: overlapping load generators would corrupt
// each other's numbers.
type RunManager struct {
	mu         sync.Mutex
	runs       map[string]*Run
	order      []string // creation order, for pruning
	active     *Run
	resultsDir string
}

func newRunManager(resultsDir string) *RunManager {
	return &RunManager{runs: make(map[string]*Run), resultsDir: resultsDir}
}

func (m *RunManager) get(id string) *Run {
	m.mu.Lock()
	defer m.mu.Unlock()
	return m.runs[id]
}

func (m *RunManager) list() []*Run {
	m.mu.Lock()
	defer m.mu.Unlock()
	out := make([]*Run, 0, len(m.order))
	for i := len(m.order) - 1; i >= 0; i-- { // newest first
		out = append(out, m.runs[m.order[i]])
	}
	return out
}

// start validates a request and launches its coordinator. It returns
// user-facing warnings (e.g. the github.com abuse note) alongside the run.
func (m *RunManager) start(req startRequest) (*Run, []string, error) {
	if !req.ConfirmAuthorized {
		return nil, nil, errors.New("confirm_authorized must be true: only benchmark infrastructure you own or are explicitly authorized to load-test")
	}
	if len(req.Targets) == 0 {
		return nil, nil, errors.New("at least one target is required")
	}
	if len(req.Targets) > maxTargets {
		return nil, nil, fmt.Errorf("at most %d targets per run", maxTargets)
	}

	ws := req.Workload.withDefaults()
	runID := bench.NewRunID()
	bw := ws.toWorkload(runID)
	if err := bw.Validate(); err != nil {
		return nil, nil, err
	}

	var warnings []string
	targets := make([]*targetState, len(req.Targets))
	for i, ts := range req.Targets {
		bt := ts.toTarget()
		name := ts.Name
		if name == "" {
			name = defaultTargetName(bt.Remote, i)
		}
		if bench.IsGitHubDotCom(bt.Remote) {
			if hi := slices.Max(bw.Concurrency); hi > 16 {
				warnings = append(warnings, fmt.Sprintf(
					"concurrency %d against github.com is likely to trip secondary rate limits / abuse detection — keep it low (e.g. 1,4)", hi))
			}
		}
		targets[i] = &targetState{id: i, name: name, spec: bt, col: &collector{}}
	}

	ctx, cancel := context.WithCancel(context.Background())
	run := &Run{
		ID: runID, StartedAt: time.Now(), log: newEventLog(),
		ctx: ctx, cancel: cancel,
		workload: ws, bw: bw, state: "starting", targets: targets,
	}

	m.mu.Lock()
	if m.active != nil {
		m.mu.Unlock()
		cancel()
		return nil, nil, errRunActive
	}
	m.active = run
	m.runs[run.ID] = run
	m.order = append(m.order, run.ID)
	m.pruneLocked()
	m.mu.Unlock()

	run.log.emit("hello", run.helloEvent())
	go run.coordinate(m)
	return run, warnings, nil
}

// pruneLocked drops the oldest finished runs beyond keepFinishedRuns.
// Caller holds m.mu.
func (m *RunManager) pruneLocked() {
	finished := 0
	for i := len(m.order) - 1; i >= 0; i-- {
		r := m.runs[m.order[i]]
		if r == m.active {
			continue
		}
		finished++
		if finished > keepFinishedRuns {
			delete(m.runs, m.order[i])
			m.order = append(m.order[:i], m.order[i+1:]...)
		}
	}
}

func (m *RunManager) clearActive(r *Run) {
	m.mu.Lock()
	defer m.mu.Unlock()
	if m.active == r {
		m.active = nil
	}
}

// coordinate is the run's driver goroutine: build runners, then walk the
// concurrency sweep with a barrier per level so every target starts each
// level at the same instant (the whole point of a comparison run).
func (r *Run) coordinate(m *RunManager) {
	defer r.cancel()

	// Resolve every target concurrently — entiredb setup probes the cluster.
	// A target that fails setup is dead but doesn't kill the comparison.
	var wg sync.WaitGroup
	for _, t := range r.targets {
		wg.Add(1)
		go func(t *targetState) {
			defer wg.Done()
			var (
				lr  levelRunner
				err error
			)
			if isDemoRemote(t.spec.Remote) {
				lr, err = newDemoRunner(t.spec.Remote, r.bw, t.col)
			} else {
				lr, err = bench.NewRunner(r.ctx, t.spec, r.bw, t.col)
			}
			t.spec.Secret = "" // consumed; nothing on the run retains it
			if err != nil {
				r.markDead(t, -1, err)
				return
			}
			r.mu.Lock()
			t.runner = lr
			t.label = lr.Label()
			r.mu.Unlock()
			r.log.emit("target_ready", map[string]any{
				"target": t.id, "label": lr.Label(), "nodes": lr.Nodes(), "object_format": lr.ObjectFormat(),
			})
		}(t)
	}
	wg.Wait()

	if r.aliveTargets() == nil {
		r.finish(m, "failed")
		return
	}
	r.setState("running")

	// One ticker per run: a single bucket event per second carries every
	// target's stats, so chart columns align by construction.
	tickerDone := make(chan struct{})
	tickerStopped := make(chan struct{})
	go func() {
		defer close(tickerStopped)
		tick := time.NewTicker(time.Second)
		defer tick.Stop()
		for {
			select {
			case <-tick.C:
				r.emitBucket()
			case <-tickerDone:
				return
			}
		}
	}()

	for li, c := range r.bw.Concurrency {
		if r.ctx.Err() != nil || r.aliveTargets() == nil {
			break
		}
		r.mu.Lock()
		r.levelIdx = li
		r.levelConc = c
		r.mu.Unlock()
		r.log.emit("level_start", map[string]any{
			"level_index": li, "concurrency": c,
			"warmup_sec": r.bw.Warmup.Seconds(), "duration_sec": r.bw.Duration.Seconds(),
			"at": time.Now().UTC(),
		})

		var lwg sync.WaitGroup
		for _, t := range r.aliveTargets() {
			lwg.Add(1)
			go func(t *targetState) {
				defer lwg.Done()
				t.col.reset()
				res, err := t.runner.RunLevel(r.ctx, c)
				if err != nil {
					r.markDead(t, li, err)
					return
				}
				r.mu.Lock()
				t.results = append(t.results, res)
				r.mu.Unlock()
			}(t)
		}
		lwg.Wait()

		results := map[string]bench.LevelResult{}
		r.mu.Lock()
		for _, t := range r.targets {
			if len(t.results) > li {
				results[strconv.Itoa(t.id)] = t.results[li]
			}
		}
		r.mu.Unlock()
		r.log.emit("level_result", map[string]any{
			"level_index": li, "concurrency": c, "targets": results,
		})
	}

	close(tickerDone)
	<-tickerStopped

	state := "done"
	if r.ctx.Err() != nil {
		state = "cancelled"
	} else if r.aliveTargets() == nil {
		state = "failed"
	}
	r.finish(m, state)
}

func (r *Run) finish(m *RunManager, state string) {
	r.setState(state)
	resultsFile := r.persistResults(m.resultsDir)
	r.mu.Lock()
	r.resultsFile = resultsFile
	r.mu.Unlock()
	r.log.emit("run_done", map[string]any{
		"state": state, "results_file": resultsFile, "at": time.Now().UTC(),
	})
	r.log.close()
	m.clearActive(r)
}

// persistResults writes the run's result doc. Wired up with the results
// package; returns the bare filename or "" when there is nothing to write.
func (r *Run) persistResults(dir string) string {
	return "" // implemented with internal/results (history phase)
}

func (r *Run) emitBucket() {
	r.mu.Lock()
	li, c := r.levelIdx, r.levelConc
	alive := make([]*targetState, 0, len(r.targets))
	for _, t := range r.targets {
		if !t.dead {
			alive = append(alive, t)
		}
	}
	r.mu.Unlock()
	if len(alive) == 0 {
		return
	}
	stats := make(map[string]BucketStats, len(alive))
	for _, t := range alive {
		stats[strconv.Itoa(t.id)] = t.col.snapshot()
	}
	r.log.emit("bucket", map[string]any{
		"level_index": li, "concurrency": c, "t": time.Now().Unix(), "targets": stats,
	})
}

func (r *Run) markDead(t *targetState, levelIdx int, err error) {
	r.mu.Lock()
	t.dead = true
	t.fatalErr = err.Error()
	r.mu.Unlock()
	r.log.emit("target_error", map[string]any{
		"target": t.id, "level_index": levelIdx, "message": err.Error(), "fatal": true,
	})
}

// aliveTargets returns the targets still participating, or nil when none are.
func (r *Run) aliveTargets() []*targetState {
	r.mu.Lock()
	defer r.mu.Unlock()
	var out []*targetState
	for _, t := range r.targets {
		if !t.dead {
			out = append(out, t)
		}
	}
	return out
}

func (r *Run) setState(s string) {
	r.mu.Lock()
	r.state = s
	r.mu.Unlock()
}

func (r *Run) helloEvent() map[string]any {
	infos := make([]TargetInfo, len(r.targets))
	for i, t := range r.targets {
		infos[i] = TargetInfo{ID: t.id, Name: t.name, Remote: t.spec.Remote}
	}
	return map[string]any{
		"run_id":     r.ID,
		"state":      "starting",
		"started_at": r.StartedAt.UTC(),
		"workload":   r.workload,
		"targets":    infos,
		"levels":     r.bw.Concurrency,
	}
}

// targetStatus is the redacted per-target view in GET responses.
type targetStatus struct {
	TargetInfo
	Label   string              `json:"label,omitempty"`
	Dead    bool                `json:"dead,omitempty"`
	Error   string              `json:"error,omitempty"`
	Results []bench.LevelResult `json:"results,omitempty"`
}

// runStatus is the redacted run view for GET /api/runs and /api/runs/{id}.
type runStatus struct {
	ID          string         `json:"id"`
	State       string         `json:"state"`
	StartedAt   time.Time      `json:"started_at"`
	Workload    WorkloadSpec   `json:"workload"`
	Levels      []int          `json:"levels"`
	LevelIndex  int            `json:"level_index"`
	Targets     []targetStatus `json:"targets"`
	ResultsFile string         `json:"results_file,omitempty"`
}

func (r *Run) status() runStatus {
	r.mu.Lock()
	defer r.mu.Unlock()
	st := runStatus{
		ID: r.ID, State: r.state, StartedAt: r.StartedAt.UTC(),
		Workload: r.workload, Levels: r.bw.Concurrency, LevelIndex: r.levelIdx,
		ResultsFile: r.resultsFile,
	}
	for _, t := range r.targets {
		st.Targets = append(st.Targets, targetStatus{
			TargetInfo: TargetInfo{ID: t.id, Name: t.name, Remote: t.spec.Remote},
			Label:      t.label, Dead: t.dead, Error: t.fatalErr,
			Results: slices.Clone(t.results),
		})
	}
	return st
}

// defaultTargetName labels an unnamed target by its remote host.
func defaultTargetName(remote string, i int) string {
	if u, err := url.Parse(remote); err == nil && u.Host != "" {
		return u.Host
	}
	return fmt.Sprintf("target-%d", i+1)
}

package server

import (
	"context"
	"fmt"
	"math"
	"math/rand"
	"net/url"
	"strconv"
	"sync"
	"time"

	"github.com/entireio/forgemark/internal/bench"
)

// demoRunner synthesizes push samples so the whole pipeline — level barriers,
// collector, SSE, charts, persistence — can be exercised and demoed with no
// forge and no network. It is selected by a demo:// remote:
//
//	demo://fast?p50=80ms&spread=3&err=0.01&cas=0.02&cap=200
//
//	p50     median latency (Go duration; default 80ms)
//	spread  p99/p50 shape multiplier of the log-normal tail (default 3)
//	err     probability an op fails (default 0.01)
//	cas     probability an op is a CAS rejection (default 0)
//	cap     ops/sec saturation ceiling; approaching it inflates latency the
//	        way a real forge queues (default 0 = unbounded)
//
// Each concurrency level runs c goroutines that sleep a sampled latency per
// op, so throughput scales with concurrency until cap bends the curve — the
// same shapes a real sweep produces.
type demoRunner struct {
	label   string
	w       bench.Workload
	sink    bench.Sink
	p50     time.Duration
	sigma   float64 // log-normal shape derived from spread
	errRate float64
	casRate float64
	cap     float64
}

func isDemoRemote(remote string) bool {
	u, err := url.Parse(remote)
	return err == nil && u.Scheme == "demo"
}

func newDemoRunner(remote string, w bench.Workload, sink bench.Sink) (*demoRunner, error) {
	u, err := url.Parse(remote)
	if err != nil || u.Scheme != "demo" {
		return nil, fmt.Errorf("invalid demo remote %q", remote)
	}
	q := u.Query()
	d := &demoRunner{label: remote, w: w, sink: sink, p50: 80 * time.Millisecond, errRate: 0.01}
	spread := 3.0
	if v := q.Get("p50"); v != "" {
		if d.p50, err = time.ParseDuration(v); err != nil || d.p50 <= 0 {
			return nil, fmt.Errorf("demo: invalid p50 %q", v)
		}
	}
	for name, dst := range map[string]*float64{"spread": &spread, "err": &d.errRate, "cas": &d.casRate, "cap": &d.cap} {
		if v := q.Get(name); v != "" {
			f, err := strconv.ParseFloat(v, 64)
			if err != nil || f < 0 {
				return nil, fmt.Errorf("demo: invalid %s %q", name, v)
			}
			*dst = f
		}
	}
	if spread < 1 {
		return nil, fmt.Errorf("demo: spread must be >= 1")
	}
	// For a log-normal around the median, p99 = median * exp(sigma * z99).
	d.sigma = math.Log(spread) / 2.326
	return d, nil
}

func (d *demoRunner) Label() string        { return d.label }
func (d *demoRunner) Nodes() int           { return 1 }
func (d *demoRunner) ObjectFormat() string { return "sha1" }

func (d *demoRunner) RunLevel(ctx context.Context, c int) (bench.LevelResult, error) {
	total := d.w.Warmup + d.w.Duration
	lctx, cancel := context.WithTimeout(ctx, total)
	defer cancel()

	// Saturation: offered load approaches cap → queueing inflates latency.
	inflate := 1.0
	if d.cap > 0 {
		offered := float64(c) / d.p50.Seconds()
		util := math.Min(offered/d.cap, 0.95)
		inflate = 1 / (1 - util)
	}

	start := time.Now()
	var mu sync.Mutex
	var all []bench.Sample
	var wg sync.WaitGroup
	for i := range c {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			// Deterministic per agent, like the engine's commit content rng.
			rng := rand.New(rand.NewSource(int64(id)*7919 + 42)) //nolint:gosec // synthetic demo data
			for lctx.Err() == nil {
				lat := time.Duration(float64(d.p50) * inflate * math.Exp(d.sigma*rng.NormFloat64()))
				t0 := time.Now()
				select {
				case <-time.After(lat):
				case <-lctx.Done():
					return // drop the truncated op, like the engine does
				}
				s := bench.Sample{Offset: t0.Sub(start), Dur: time.Since(t0)}
				switch roll := rng.Float64(); {
				case roll < d.errRate:
					s.Res = bench.OutcomeErr
					s.Msg = "demo: synthetic error"
				case roll < d.errRate+d.casRate:
					s.Res = bench.OutcomeCAS
				}
				if d.sink != nil {
					d.sink.OnSample(s)
				}
				mu.Lock()
				all = append(all, s)
				mu.Unlock()
			}
		}(i)
	}
	wg.Wait()
	return bench.SummarizeSamples(all, c, d.w.Strategy, 1, 1, d.w.Warmup, d.w.Duration, d.w.CommitDesc()), nil
}

// Package server is the forgemark web GUI: a localhost HTTP server that runs
// benchmark sweeps (one or many targets, level-aligned) over internal/bench
// and streams live per-second stats to an embedded single-page UI over SSE.
package server

import (
	"context"
	"embed"
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"net"
	"net/http"
	"net/url"
	"time"
)

//go:embed static
var staticFiles embed.FS

type Server struct {
	addr string
	mgr  *RunManager
	mux  *http.ServeMux
}

// New builds the server. resultsDir is where finished runs are persisted and
// where history is read from (shared with the CLI's results/ by default).
func New(addr, resultsDir string) *Server {
	s := &Server{addr: addr, mgr: newRunManager(resultsDir), mux: http.NewServeMux()}

	staticRoot, err := fs.Sub(staticFiles, "static")
	if err != nil {
		panic("embedded static assets missing: " + err.Error()) // build-time invariant
	}
	s.mux.Handle("GET /", http.FileServerFS(staticRoot))

	s.mux.HandleFunc("POST /api/runs", s.requireLocalOrigin(s.handleStartRun))
	s.mux.HandleFunc("GET /api/runs", s.handleListRuns)
	s.mux.HandleFunc("GET /api/runs/{id}", s.handleGetRun)
	s.mux.HandleFunc("POST /api/runs/{id}/cancel", s.requireLocalOrigin(s.handleCancelRun))
	s.mux.HandleFunc("GET /api/runs/{id}/events", s.handleRunEvents)
	s.mux.HandleFunc("GET /api/history", s.handleHistory)
	s.mux.HandleFunc("GET /api/history/{file}", s.handleHistoryDoc)
	return s
}

// Handler exposes the mux for httptest.
func (s *Server) Handler() http.Handler { return s.mux }

// ListenAndServe blocks until ctx is cancelled or the listener fails.
func (s *Server) ListenAndServe(ctx context.Context) error {
	srv := &http.Server{Addr: s.addr, Handler: s.mux, ReadHeaderTimeout: 10 * time.Second}
	errc := make(chan error, 1)
	go func() { errc <- srv.ListenAndServe() }()
	select {
	case err := <-errc:
		return err
	case <-ctx.Done():
		shutCtx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
		defer cancel()
		_ = srv.Shutdown(shutCtx)
		return nil
	}
}

// requireLocalOrigin guards mutating endpoints against DNS-rebinding/CSRF: the
// UI pastes credentials, so a hostile web page must not be able to drive this
// API. Browsers always send Origin on cross-origin POSTs; a request with no
// Origin header is curl or same-origin-old-browser, which is fine for a
// loopback tool.
func (s *Server) requireLocalOrigin(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		if origin := r.Header.Get("Origin"); origin != "" {
			u, err := url.Parse(origin)
			if err != nil || !isLoopbackHost(u.Hostname()) {
				http.Error(w, "forbidden origin", http.StatusForbidden)
				return
			}
		}
		next(w, r)
	}
}

func isLoopbackHost(host string) bool {
	if host == "localhost" {
		return true
	}
	ip := net.ParseIP(host)
	return ip != nil && ip.IsLoopback()
}

func (s *Server) handleStartRun(w http.ResponseWriter, r *http.Request) {
	var req startRequest
	dec := json.NewDecoder(http.MaxBytesReader(w, r.Body, 1<<20))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&req); err != nil {
		httpError(w, http.StatusBadRequest, fmt.Sprintf("bad request body: %v", err))
		return
	}
	run, warnings, err := s.mgr.start(req)
	if err != nil {
		code := http.StatusBadRequest
		if errors.Is(err, errRunActive) {
			code = http.StatusConflict
		}
		httpError(w, code, err.Error())
		return
	}
	writeJSON(w, http.StatusCreated, map[string]any{"id": run.ID, "warnings": warnings})
}

func (s *Server) handleListRuns(w http.ResponseWriter, _ *http.Request) {
	runs := s.mgr.list()
	out := make([]runStatus, len(runs))
	for i, r := range runs {
		out[i] = r.status()
	}
	writeJSON(w, http.StatusOK, out)
}

func (s *Server) handleGetRun(w http.ResponseWriter, r *http.Request) {
	run := s.mgr.get(r.PathValue("id"))
	if run == nil {
		httpError(w, http.StatusNotFound, "no such run")
		return
	}
	writeJSON(w, http.StatusOK, run.status())
}

func (s *Server) handleCancelRun(w http.ResponseWriter, r *http.Request) {
	run := s.mgr.get(r.PathValue("id"))
	if run == nil {
		httpError(w, http.StatusNotFound, "no such run")
		return
	}
	run.cancel()
	writeJSON(w, http.StatusOK, map[string]any{"id": run.ID, "cancelling": true})
}

func (s *Server) handleRunEvents(w http.ResponseWriter, r *http.Request) {
	run := s.mgr.get(r.PathValue("id"))
	if run == nil {
		httpError(w, http.StatusNotFound, "no such run")
		return
	}
	serveSSE(w, r, run.log)
}

func writeJSON(w http.ResponseWriter, code int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(code)
	_ = json.NewEncoder(w).Encode(v)
}

func httpError(w http.ResponseWriter, code int, msg string) {
	writeJSON(w, code, map[string]string{"error": msg})
}

// Package results reads and writes forgemark result documents. Two formats
// exist on disk in the same results/ directory:
//
//	format 1 (legacy, no "format" field): what the CLI has always written —
//	    one target, top-level "target"/"levels" fields. The CLI keeps writing
//	    this shape for strict compatibility with existing tooling.
//	format 2: what the server writes — multi-target, per-target level results
//	    plus the per-second live series so a finished run re-renders fully.
//
// Load normalizes format 1 into a one-target format 2 view, so consumers (the
// history UI) only ever see one shape.
package results

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"time"

	"github.com/entireio/forgemark/internal/bench"
)

// Doc is a stored run. Exactly one of the two shapes is populated on disk;
// Load always returns the Targets shape.
type Doc struct {
	Format   int    `json:"format,omitempty"` // 2; absent/0 = legacy CLI doc
	RunID    string `json:"run_id"`
	Strategy string `json:"strategy"`
	Duration string `json:"duration"`
	Warmup   string `json:"warmup"`
	Commit   string `json:"commit"`

	// format 2
	State   string         `json:"state,omitempty"` // done | cancelled | failed
	Targets []TargetResult `json:"targets,omitempty"`

	// format 1 (legacy CLI)
	Target    string              `json:"target,omitempty"`
	RepoCount int                 `json:"repo_count,omitempty"`
	Levels    []bench.LevelResult `json:"levels,omitempty"`
}

// TargetResult is one target's outcome within a run.
type TargetResult struct {
	Name   string              `json:"name"`
	Label  string              `json:"label,omitempty"`
	Error  string              `json:"error,omitempty"` // fatal target error, if it died
	Levels []bench.LevelResult `json:"levels"`
	Series []SeriesPoint       `json:"series,omitempty"` // 1s live buckets, for re-rendering
}

// SeriesPoint is one second of one target's live stats.
type SeriesPoint struct {
	T     int64   `json:"t"`
	Level int     `json:"level"`
	OK    int     `json:"ok"`
	CAS   int     `json:"cas"`
	Err   int     `json:"err"`
	P50   float64 `json:"p50_ms"`
	P95   float64 `json:"p95_ms"`
	P99   float64 `json:"p99_ms"`
}

// Summary is one history listing entry.
type Summary struct {
	File     string    `json:"file"`
	RunID    string    `json:"run_id"`
	Strategy string    `json:"strategy"`
	State    string    `json:"state,omitempty"`
	Targets  []string  `json:"targets"`
	Levels   int       `json:"levels"`
	ModTime  time.Time `json:"mtime"`
}

// ErrNotFound reports a missing result file.
var ErrNotFound = errors.New("result file not found")

// validFile is the only filename shape this package will touch. It doubles as
// the path-traversal guard for filenames arriving from HTTP.
var validFile = regexp.MustCompile(`^forgemark-[A-Za-z0-9._-]+\.json$`)

// Write stores a format-2 doc as <dir>/<file>, creating dir if needed.
func Write(dir, file string, doc Doc) error {
	if !validFile.MatchString(file) {
		return fmt.Errorf("invalid result filename %q", file)
	}
	if err := os.MkdirAll(dir, 0o750); err != nil {
		return fmt.Errorf("mkdir %s: %w", dir, err)
	}
	b, err := json.MarshalIndent(doc, "", "  ")
	if err != nil {
		return fmt.Errorf("marshal results: %w", err)
	}
	if err := os.WriteFile(filepath.Join(dir, file), b, 0o600); err != nil {
		return fmt.Errorf("write results: %w", err)
	}
	return nil
}

// List summarizes every parseable result doc in dir, newest first. Unparseable
// files are skipped, not fatal — the directory is shared and hand-editable.
func List(dir string) ([]Summary, error) {
	entries, err := os.ReadDir(dir)
	if errors.Is(err, os.ErrNotExist) {
		return []Summary{}, nil
	}
	if err != nil {
		return nil, err
	}
	out := []Summary{}
	for _, e := range entries {
		if e.IsDir() || !validFile.MatchString(e.Name()) {
			continue
		}
		doc, err := Load(dir, e.Name())
		if err != nil {
			continue
		}
		info, err := e.Info()
		if err != nil {
			continue
		}
		s := Summary{
			File: e.Name(), RunID: doc.RunID, Strategy: doc.Strategy,
			State: doc.State, ModTime: info.ModTime(),
		}
		for _, t := range doc.Targets {
			s.Targets = append(s.Targets, t.Name)
			s.Levels = max(s.Levels, len(t.Levels))
		}
		out = append(out, s)
	}
	// Newest first: the history view leads with the latest run.
	for i := 0; i < len(out)/2; i++ {
		out[i], out[len(out)-1-i] = out[len(out)-1-i], out[i]
	}
	return out, nil
}

// Load reads one doc and normalizes legacy CLI docs into the Targets shape.
func Load(dir, file string) (Doc, error) {
	if !validFile.MatchString(file) {
		return Doc{}, fmt.Errorf("invalid result filename %q", file)
	}
	b, err := os.ReadFile(filepath.Join(dir, file))
	if errors.Is(err, os.ErrNotExist) {
		return Doc{}, ErrNotFound
	}
	if err != nil {
		return Doc{}, err
	}
	var doc Doc
	if err := json.Unmarshal(b, &doc); err != nil {
		return Doc{}, fmt.Errorf("parse %s: %w", file, err)
	}
	if doc.Format == 0 && len(doc.Targets) == 0 {
		// Legacy CLI doc: present it as one pseudo-target named by its label.
		doc.Targets = []TargetResult{{Name: doc.Target, Label: doc.Target, Levels: doc.Levels}}
		doc.State = "done"
	}
	doc.Target, doc.Levels = "", nil // consumers only see the normalized shape
	return doc, nil
}

