/* ForgeMark dashboard — dark theme.
   Chrome/ink/palette values follow the validated reference palette
   (dark surface #1a1a19; categorical slots stepped for it). */

:root {
  --page:        #0d0d0d;
  --surface:     #1a1a19;
  --surface-2:   #222221;
  --ink:         #ffffff;
  --ink-2:       #c3c2b7;
  --muted:       #898781;
  --grid:        #2c2c2a;
  --baseline:    #383835;
  --border:      rgba(255, 255, 255, 0.10);
  --good:        #0ca30c;
  --warning:     #fab219;
  --critical:    #d03b3b;
  --accent:      #3987e5;

  --s1: #3987e5; /* blue    */
  --s2: #199e70; /* aqua    */
  --s3: #c98500; /* yellow  */
  --s4: #008300; /* green   */
  --s5: #9085e9; /* violet  */
  --s6: #e66767; /* red     */
  --s7: #d55181; /* magenta */
  --s8: #d95926; /* orange  */
}

* { box-sizing: border-box; }

body {
  margin: 0;
  background: var(--page);
  color: var(--ink-2);
  font: 14px/1.5 system-ui, -apple-system, "Segoe UI", sans-serif;
}

/* ---------- chrome ---------- */

.topbar {
  display: flex;
  align-items: center;
  gap: 28px;
  padding: 0 24px;
  height: 52px;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 10;
}
.brand {
  font-weight: 700;
  font-size: 16px;
  color: var(--ink);
  text-decoration: none;
  letter-spacing: 0.2px;
}
.brand span { color: var(--accent); }
.topbar nav { display: flex; gap: 4px; }
.topbar nav a {
  color: var(--ink-2);
  text-decoration: none;
  padding: 6px 12px;
  border-radius: 6px;
  font-weight: 500;
}
.topbar nav a:hover { background: var(--surface-2); color: var(--ink); }
.topbar nav a.active { background: var(--surface-2); color: var(--ink); }

main { max-width: 1180px; margin: 0 auto; padding: 24px; }

h1 { font-size: 20px; color: var(--ink); margin: 0 0 4px; }
h2 { font-size: 15px; color: var(--ink); margin: 0 0 12px; }
.sub { color: var(--muted); margin: 0 0 20px; }

.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 18px 20px;
  margin-bottom: 16px;
