// Thin fetch wrappers over the forgemark API. All errors surface as thrown
// Error objects carrying the server's message.

async function req(method, path, body) {
  const res = await fetch(path, {
    method,
    headers: body ? { 'Content-Type': 'application/json' } : undefined,
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await res.text();
  let data = null;
  try { data = text ? JSON.parse(text) : null; } catch { /* non-JSON error body */ }
  if (!res.ok) {
    throw new Error((data && data.error) || `${res.status} ${res.statusText}`);
  }
  return data;
}

export const api = {
  startRun: (spec) => req('POST', '/api/runs', spec),
  listRuns: () => req('GET', '/api/runs'),
  getRun: (id) => req('GET', `/api/runs/${encodeURIComponent(id)}`),
  cancelRun: (id) => req('POST', `/api/runs/${encodeURIComponent(id)}/cancel`),
  history: () => req('GET', '/api/history'),
  historyDoc: (file) => req('GET', `/api/history/${encodeURIComponent(file)}`),
};

// EventSource wrapper for a run's event stream. The browser reconnects
// automatically and re-sends Last-Event-ID; the server replays anything
// missed, so handlers can treat the stream as gapless and in-order. The
// caller closes it on run_done — after that the stream only ever replays.

export function openRunStream(runId, handlers) {
  const es = new EventSource(`/api/runs/${encodeURIComponent(runId)}/events`);
  for (const [name, fn] of Object.entries(handlers)) {
    es.addEventListener(name, (ev) => fn(JSON.parse(ev.data)));
  }
  return es;
}

// uPlot helpers. All charts share the dark chart chrome and the fixed
// categorical target palette: color follows the target index, never the
// series' position in a particular chart.

export const PALETTE = [
  '#3987e5', '#199e70', '#c98500', '#008300',
  '#9085e9', '#e66767', '#d55181', '#d95926',
];
export const targetColor = (i) => PALETTE[i % PALETTE.length];

const INK_MUTED = '#898781';
const GRID = '#2c2c2a';
const BASELINE = '#383835';

const axisFont = '12px system-ui, sans-serif';

function baseAxes(unitFmt) {
  return [
    {
      stroke: INK_MUTED, font: axisFont,
      grid: { stroke: GRID, width: 1 },
      ticks: { stroke: BASELINE, width: 1 },
    },
    {
      stroke: INK_MUTED, font: axisFont, size: 56,
      grid: { stroke: GRID, width: 1 },
      ticks: { show: false },
      values: (u, splits) => splits.map((v) => (v == null ? '' : unitFmt(v))),
    },
  ];
}

export const fmtNum = (v) => {
  if (v == null) return '';
  if (v >= 1000) return (v / 1000).toFixed(1) + 'k';
  return v >= 100 ? v.toFixed(0) : +v.toFixed(1) + '';
};
export const fmtMs = (v) => (v == null ? '' : v >= 1000 ? (v / 1000).toFixed(1) + 's' : Math.round(v) + 'ms');

// timeChart: a streaming time-series chart. `series` is
// [{label, color, dash?}] — one per plotted line. `bands()` returns
// [{from,to}] x-ranges (unix secs) shaded as warm-up. push()/setAll() update
// the data; the chart resizes with its container.
export function timeChart(el, { series, unit = fmtNum, height = 240, bands = () => [] }) {
  const data = [[], ...series.map(() => [])];

  const opts = {
    width: el.clientWidth || 800,
    height,
    ms: false,
    cursor: { points: { size: 7 } },
    scales: { x: { time: true } },
    axes: baseAxes(unit),
    legend: { live: true },
    series: [
      { value: (u, ts) => (ts == null ? '' : new Date(ts * 1000).toLocaleTimeString()) },
      ...series.map((s) => ({
        label: s.label,
        stroke: s.color,
        width: 2,
        dash: s.dash,
        spanGaps: false,
        points: { show: false },
        value: (u, v) => (v == null ? '–' : unit(v)),
      })),
    ],
    hooks: {
      drawClear: [
        (u) => {
          // Warm-up shading: quieter than data, under the series.
          const { ctx } = u;
          ctx.save();
          ctx.fillStyle = 'rgba(137, 135, 129, 0.07)';
          for (const b of bands()) {
            const x0 = u.valToPos(b.from, 'x', true);
            const x1 = u.valToPos(b.to, 'x', true);
            ctx.fillRect(x0, u.bbox.top, x1 - x0, u.bbox.height);
          }
          ctx.restore();
        },
      ],
    },
  };

  const u = new uPlot(opts, data, el);
  const ro = new ResizeObserver(() => u.setSize({ width: el.clientWidth, height }));
  ro.observe(el);

  return {
    u,
    push(ts, vals) {
      data[0].push(ts);
      vals.forEach((v, i) => data[i + 1].push(v));
      u.setData(data);
    },
    setAll(rows) {
      // rows: [[ts, v1, v2, …], …]
      for (let i = 0; i < data.length; i++) data[i] = rows.map((r) => r[i] ?? null);
      u.setData(data);
    },
    destroy() { ro.disconnect(); u.destroy(); },
  };
}

// sweepChart: results vs concurrency (log-2 x), for finished-run comparison.
// seriesData: [{label, color, points: [[concurrency, value], …]}].
export function sweepChart(el, { seriesData, unit = fmtNum, height = 260 }) {
  const xs = [...new Set(seriesData.flatMap((s) => s.points.map((p) => p[0])))].sort((a, b) => a - b);
  const data = [xs, ...seriesData.map((s) => {
    const byX = new Map(s.points);
    return xs.map((x) => byX.has(x) ? byX.get(x) : null);
  })];

  const opts = {
    width: el.clientWidth || 800,
    height,
    cursor: { points: { size: 8 } },
    scales: { x: { time: false, distr: 3, log: 2 } },
    axes: [
      { ...baseAxes(unit)[0], values: (u, splits) => splits.map((v) => (v == null ? '' : String(v))) },
      baseAxes(unit)[1],
    ],
    legend: { live: true },
    series: [
      { label: 'concurrency' },
      ...seriesData.map((s) => ({
        label: s.label,
        stroke: s.color,
        width: 2,
        spanGaps: true,
        points: { show: true, size: 7, fill: s.color },
        value: (u, v) => (v == null ? '–' : unit(v)),
      })),
    ],
  };

  const u = new uPlot(opts, data, el);
  const ro = new ResizeObserver(() => u.setSize({ width: el.clientWidth, height }));
  ro.observe(el);
  return { u, destroy() { ro.disconnect(); u.destroy(); } };
}

// Tiny DOM builder: h('div', {class: 'card', onclick: fn}, child, …).
// Strings become text nodes; arrays flatten; null/undefined are skipped.

export function h(tag, attrs = {}, ...children) {
  const el = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs || {})) {
    if (v == null) continue;
    if (k.startsWith('on') && typeof v === 'function') {
      el.addEventListener(k.slice(2), v);
    } else if (k === 'dataset') {
      Object.assign(el.dataset, v);
    } else if (k === 'style' && typeof v === 'object') {
      Object.assign(el.style, v);
    } else if (k in el && k !== 'type' && k !== 'value') {
      try { el[k] = v; } catch { el.setAttribute(k, v); }
    } else {
      el.setAttribute(k, v);
    }
  }
  append(el, children);
  return el;
}

function append(el, kids) {
  for (const k of kids) {
    if (k == null) continue;
    if (Array.isArray(k)) { append(el, k); continue; }
    el.append(k.nodeType ? k : document.createTextNode(String(k)));
  }
}

// Hash router. Each view renders into #app and may return a cleanup function
// (close EventSources, destroy charts, clear timers) called on navigation.

import { renderNewRun } from './views/newrun.js';
import { renderDashboard } from './views/dashboard.js';
import { renderHistory } from './views/history.js';
import { renderRuns } from './views/runs.js';

let cleanup = null;

function route() {
  if (cleanup) { try { cleanup(); } catch { /* view teardown is best-effort */ } cleanup = null; }
  const app = document.getElementById('app');
  app.innerHTML = '';

  const hash = location.hash || '#new';
  const [, view, arg] = hash.match(/^#([^/]*)\/?(.*)$/) || [];

  for (const a of document.querySelectorAll('[data-nav]')) {
    a.classList.toggle('active', a.dataset.nav === view || (view === 'run' && a.dataset.nav === 'runs'));
  }

  let out = null;
  if (view === 'run' && arg) out = renderDashboard(app, arg);
  else if (view === 'runs') out = renderRuns(app);
  else if (view === 'history') out = renderHistory(app);
  else out = renderNewRun(app);
  if (typeof out === 'function') cleanup = out;
}

window.addEventListener('hashchange', route);
route();

// New-run form: one workload, 1..8 targets. Secrets go straight into the POST
// body and nowhere else (no localStorage, no URL).

import { h } from '../dom.js';
import { api } from '../api.js';
import { targetColor } from '../charts.js';

const strategies = [
  ['branch', 'branch — one repo, per-agent branches (headline write number)'],
  ['repo', 'repo — agents spread across N repos (horizontal scale)'],
  ['clone', 'clone — shallow-clone loop (read-side ceiling)'],
  ['session', 'session — clone + push checkpoints per session (agent lifecycle)'],
];

let targetSeq = 0;

function blankTarget() {
  return { key: ++targetSeq, name: '', remote: '', repos: '', user: '', secret: '', insecure: false, object_format: 'auto', token_url: '', jurisdiction: '', client_id: '' };
}

export function renderNewRun(app) {
  const targets = [blankTarget()];
  let errorBanner = null;

  const targetsBox = h('div');
  const startBtn = h('button', { class: 'primary', type: 'submit', disabled: true }, 'Start benchmark');
  const confirm = h('input', { type: 'checkbox', id: 'confirm', onchange: () => { startBtn.disabled = !confirm.checked; } });

  function field(label, input, cls = '') {
    return h('div', { class: `field ${cls}` }, h('label', {}, label), input);
  }
  const inp = (attrs) => h('input', { type: 'text', ...attrs });

  // --- workload inputs (queried on submit) ---
  const w = {
    strategy: h('select', { onchange: () => syncStrategy() }, strategies.map(([v, t]) => h('option', { value: v }, t))),
    concurrency: inp({ value: '1,8,32', placeholder: 'e.g. 1,8,32,128' }),
    duration_sec: inp({ value: '60' }),
    warmup_sec: inp({ value: '10' }),
    files_min: inp({ value: '1' }),
    files_max: inp({ value: '10' }),
    file_size: inp({ value: '2048' }),
    branch_prefix: inp({ value: '', placeholder: 'e.g. bench/' }),
    session_commits: inp({ value: '5' }),
    clone_depth: inp({ value: '1' }),
    base_ref: inp({ value: '', placeholder: 'default branch' }),
  };

  const commitFields = h('div', { class: 'grid c3' },
    field('Files per commit (min)', w.files_min),
    field('Files per commit (max)', w.files_max),
    field('Bytes per file', w.file_size));
  const cloneFields = h('div', { class: 'grid c3' },
    field('Session commits', w.session_commits),
    field('Clone depth (0 = full)', w.clone_depth),
    field('Base ref', w.base_ref));

  function syncStrategy() {
    const s = w.strategy.value;
    commitFields.style.display = s === 'clone' ? 'none' : '';
    cloneFields.style.display = (s === 'clone' || s === 'session') ? '' : 'none';
    w.session_commits.parentElement.style.display = s === 'session' ? '' : 'none';
  }

  function renderTargets() {
    targetsBox.innerHTML = '';
    targets.forEach((t, i) => targetsBox.append(targetCard(t, i)));
  }

  function targetCard(t, i) {
    const bind = (key, input) => {
      input.value = t[key];
      input.addEventListener('input', () => { t[key] = input.value; });
      return input;
    };
    const insecure = h('input', { type: 'checkbox', style: { width: 'auto' }, onchange: (e) => { t.insecure = e.target.checked; } });
    insecure.checked = t.insecure;
    return h('div', { class: 'target-card', style: { '--tcolor': targetColor(i) } },
      h('div', { class: 'thead' },
        h('span', { class: 'tname' }, h('span', { class: 'dot', style: { '--tcolor': targetColor(i), marginRight: '8px' } }), `Target ${i + 1}`),
        targets.length > 1 ? h('button', { class: 'small danger', type: 'button', onclick: () => { targets.splice(i, 1); renderTargets(); } }, 'Remove') : null),
      h('div', { class: 'grid c3' },
        field('Name (chart label)', bind('name', inp({ placeholder: 'e.g. gitlab-prod' }))),
        field('Remote base URL', bind('remote', inp({ placeholder: 'https://gitlab.example — or demo://fast?p50=80ms' })), 'wide'),
      ),
      h('div', { class: 'grid c3', style: { marginTop: '12px' } },
        field('Repos (comma-separated)', bind('repos', inp({ placeholder: 'group/bench.git' }))),
        field('Username (token forges ignore it)', bind('user', inp({ placeholder: 'x-access-token' }))),
        field('Token / secret', bind('secret', inp({ type: 'password', autocomplete: 'off', placeholder: 'kept in memory only' }))),
      ),
      h('div', { class: 'grid c3', style: { marginTop: '12px' } },
        field('Object format', bind('object_format', h('select', {},
          h('option', { value: 'auto' }, 'auto'), h('option', { value: 'sha1' }, 'sha1'), h('option', { value: 'sha256' }, 'sha256')))),
        h('div', { class: 'field' }, h('label', {}, 'TLS'), h('label', { style: { color: 'var(--ink-2)', fontSize: '13px' } }, insecure, ' skip verification (dev hosts)')),
      ),
      h('details', { class: 'entire' },
        h('summary', {}, 'entiredb (jurisdiction token exchange)'),
        h('div', { class: 'grid c3' },
          field('Token URL', bind('token_url', inp({ placeholder: 'https://…/oauth/token' }))),
          field('Jurisdiction', bind('jurisdiction', inp({ placeholder: 'https://us.example.com' }))),
          field('Client ID', bind('client_id', inp({ placeholder: 'entire-cli' }))))));
  }

  async function submit(ev) {
    ev.preventDefault();
    if (errorBanner) { errorBanner.remove(); errorBanner = null; }
    const num = (el) => parseFloat(el.value || '0');
    const spec = {
      confirm_authorized: confirm.checked,
      workload: {
        strategy: w.strategy.value,
        concurrency: w.concurrency.value.split(',').map((s) => parseInt(s.trim(), 10)).filter((n) => n > 0),
        duration_sec: num(w.duration_sec),
        warmup_sec: num(w.warmup_sec),
        files_min: num(w.files_min), files_max: num(w.files_max), file_size: num(w.file_size),
        branch_prefix: w.branch_prefix.value,
        session_commits: num(w.session_commits), clone_depth: num(w.clone_depth), base_ref: w.base_ref.value,
      },
      targets: targets.map((t) => ({
        name: t.name, remote: t.remote,
        repos: t.repos.split(',').map((s) => s.trim()).filter(Boolean),
        user: t.user, secret: t.secret, insecure: t.insecure, object_format: t.object_format,
        token_url: t.token_url, jurisdiction: t.jurisdiction, client_id: t.client_id,
      })),
    };
    startBtn.disabled = true;
    try {
      const res = await api.startRun(spec);
      if (res.warnings && res.warnings.length) {
        sessionStorage.setItem(`fm-warn-${res.id}`, JSON.stringify(res.warnings));
      }
      location.hash = `#run/${res.id}`;
    } catch (err) {
      startBtn.disabled = !confirm.checked;
      errorBanner = h('div', { class: 'banner error' }, String(err.message || err));
      form.prepend(errorBanner);
      window.scrollTo(0, 0);
    }
  }

  const form = h('form', { onsubmit: submit },
    h('h1', {}, 'New benchmark run'),
    h('p', { class: 'sub' }, 'Drive real git pushes and clones against one or more forges and watch them side by side. Try it instantly with a ', h('code', {}, 'demo://'), ' target — no forge needed.'),
    h('div', { class: 'card' },
      h('h2', {}, 'Workload'),
      h('div', { class: 'grid c4' },
        field('Strategy', w.strategy, 'wide'),
        field('Concurrency sweep', w.concurrency),
        field('Duration per level (s)', w.duration_sec),
        field('Warm-up (s)', w.warmup_sec),
        field('Branch prefix', w.branch_prefix)),
      h('div', { style: { marginTop: '12px' } }, commitFields),
      h('div', { style: { marginTop: '12px' } }, cloneFields)),
    h('div', { class: 'card' },
      h('h2', {}, 'Targets'),
      targetsBox,
      h('div', { style: { display: 'flex', gap: '10px' } },
        h('button', { type: 'button', onclick: () => { if (targets.length < 8) { targets.push(blankTarget()); renderTargets(); } } }, '+ Add target'),
        h('button', { type: 'button', class: 'small', onclick: () => {
          targets.push({ ...blankTarget(), name: 'demo-fast', remote: 'demo://fast?p50=60ms&spread=3&err=0.01&cap=400' });
          targets.push({ ...blankTarget(), name: 'demo-slow', remote: 'demo://slow?p50=180ms&spread=4&err=0.03&cas=0.02&cap=120' });
          if (targets.length > 2 && !targets[0].remote) targets.shift();
          renderTargets();
        } }, 'Add demo pair'))),
    h('div', { class: 'confirm-row' },
      confirm,
      h('label', { for: 'confirm' }, 'I own this infrastructure or am explicitly authorized to load-test it. A benchmark run is sustained, abusive-looking traffic to any host that has not agreed to it.')),
    startBtn);

  app.append(form);
  renderTargets();
  syncStrategy();
}

// Live run dashboard. All state derives from the SSE event stream — a fresh
// page load, a late join, and a mid-run reconnect are the same code path
// (server replays from Last-Event-ID).

import { h } from '../dom.js';
import { api } from '../api.js';
import { openRunStream } from '../sse.js';
import { timeChart, targetColor, fmtNum, fmtMs } from '../charts.js';

export function renderDashboard(app, runId) {
  const state = {
    hello: null,
    strategy: '',
    warmups: [],      // [{from, to}] unix-sec ranges for shading
    latRows: [],      // [ts, ...per-target {p50,p95,p99}] for percentile switching
    totals: {},       // per target id: {ok, cas, err, lastOps, p95}
    curLevel: null,   // latest level_start payload
    done: null,
  };
  let charts = {};
  let es = null;
  let ticker = null;
  let pct = 'p95';

  // --- static skeleton ---
  const badge = h('span', { class: 'badge running' }, 'connecting…');
  const cancelBtn = h('button', { class: 'danger small', style: { display: 'none' }, onclick: async () => {
    cancelBtn.disabled = true;
    try { await api.cancelRun(runId); } catch { cancelBtn.disabled = false; }
  } }, 'Cancel run');
  const workloadNote = h('span', { class: 'progress-note' });
  const levelsStrip = h('div', { class: 'levels-strip' });
  const banners = h('div');
  const tiles = h('div', { class: 'tiles' });
  const chartsBox = h('div');
  const resultsBox = h('div');

  app.append(
    h('div', { class: 'run-head' },
      h('h1', {}, `Run ${runId}`), badge, workloadNote, h('span', { class: 'spacer' }), cancelBtn),
    banners, levelsStrip, tiles, chartsBox, resultsBox);

  const warned = sessionStorage.getItem(`fm-warn-${runId}`);
  if (warned) {
    for (const wtext of JSON.parse(warned)) banners.append(h('div', { class: 'banner warn' }, '⚠ ' + wtext));
  }

  // --- charts are built once targets are known (hello) ---
  function buildCharts(targets) {
    const isClone = state.strategy === 'clone';
    const isSession = state.strategy === 'session';
    const bands = () => state.warmups;

    const mk = (title, note, opts) => {
      const el = h('div');
      const head = h('div', { class: 'chart-head' }, h('h2', {}, title), note ? h('span', { class: 'u-note' }, note) : null);
      const card = h('div', { class: 'card chart-card' }, head, el);
      chartsBox.append(card);
      return { el, head, chart: timeChart(el, opts) };
    };

    const tputSeries = targets.map((t) => ({ label: t.name, color: targetColor(t.id) }));
    if (isSession) {
      for (const t of targets) tputSeries.push({ label: `${t.name} clones`, color: targetColor(t.id), dash: [5, 5] });
    }
    charts.tput = mk(isClone ? 'Clone throughput' : 'Push throughput',
      isClone ? 'successful clones per second' : 'successful pushes per second' + (isSession ? ' · dashed = clones/s' : ''),
      { series: tputSeries, unit: fmtNum, bands }).chart;

    const latHead = mk('Latency', `rolling 10s window · shaded = warm-up`, {
      series: targets.map((t) => ({ label: t.name, color: targetColor(t.id) })),
      unit: fmtMs, bands,
    });
    charts.lat = latHead.chart;
    const seg = h('div', { class: 'seg' }, ['p50', 'p95', 'p99'].map((p) =>
      h('button', { type: 'button', class: p === pct ? 'on' : '', onclick: (ev) => {
        pct = p;
        for (const b of seg.querySelectorAll('button')) b.classList.toggle('on', b.textContent === p);
        refeedLatency();
      } }, p)));
    latHead.head.append(seg);

    const errSeries = [];
    for (const t of targets) errSeries.push({ label: `${t.name} err`, color: targetColor(t.id) });
    for (const t of targets) errSeries.push({ label: `${t.name} cas`, color: targetColor(t.id), dash: [5, 5] });
    charts.err = mk('Errors & contention', 'failures/s (solid) and CAS rejections/s (dashed)',
      { series: errSeries, unit: fmtNum, bands }).chart;
  }

  function refeedLatency() {
    if (!charts.lat) return;
    charts.lat.setAll(state.latRows.map((r) => [r.ts, ...r.vals.map((v) => (v ? v[pct] : null))]));
  }

  function buildTiles(targets) {
    tiles.innerHTML = '';
    for (const t of targets) {
      state.totals[t.id] = { ok: 0, cas: 0, err: 0, lastOps: 0, p95: 0 };
      t._tile = {
        ops: h('b', {}, '–'), p95: h('b', {}, '–'), errs: h('b', {}, '0'),
        label: h('div', { class: 'tlabel' }, t.remote),
        err: h('div', { class: 'terr', style: { display: 'none' } }),
        root: null,
      };
      t._tile.root = h('div', { class: 'tile', style: { '--tcolor': targetColor(t.id) } },
        h('div', { class: 'tname' }, h('span', { class: 'dot', style: { '--tcolor': targetColor(t.id) } }), t.name),
        t._tile.label,
        h('div', { class: 'stats' },
          h('div', { class: 'stat' }, t._tile.ops, h('span', {}, 'ops/s')),
          h('div', { class: 'stat' }, t._tile.p95, h('span', {}, 'p95 (10s)')),
          h('div', { class: 'stat' }, t._tile.errs, h('span', {}, 'errors'))),
        t._tile.err);
      tiles.append(t._tile.root);
    }
  }

  function renderLevels() {
    levelsStrip.innerHTML = '';
    const levels = state.hello ? state.hello.levels : [];
    const curIdx = state.curLevel ? state.curLevel.level_index : -1;
    levels.forEach((c, i) => {
      const cls = state.done || i < curIdx ? 'done' : i === curIdx ? 'current' : '';
      levelsStrip.append(h('span', { class: `level-chip ${cls}` }, `c=${c}`));
    });
    levelsStrip.append(progressBar, progressNote);
  }
  const progressBar = h('div', { class: 'progress' }, h('div', { style: { width: '0%' } }));
  const progressNote = h('span', { class: 'progress-note' });

  function tickProgress() {
    if (!state.curLevel || state.done) { progressBar.firstChild.style.width = state.done ? '100%' : '0%'; return; }
    const l = state.curLevel;
    const t0 = Date.parse(l.at) / 1000;
    const total = l.warmup_sec + l.duration_sec;
    const elapsed = Math.min(Date.now() / 1000 - t0, total);
    progressBar.firstChild.style.width = `${(elapsed / total) * 100}%`;
    const remain = Math.max(0, Math.round(total - elapsed));
    progressNote.textContent = elapsed < l.warmup_sec
      ? `level ${l.level_index + 1}: warming up · ${remain}s left`
      : `level ${l.level_index + 1}: measuring · ${remain}s left`;
  }

  // --- results table ---
  const resultCols = [
    ['c', (r) => r.concurrency], ['ok', (r) => r.ok], ['ops/s', (r) => r.ops_per_sec.toFixed(1)],
    ['p50', (r) => fmtMs(r.p50_ms)], ['p95', (r) => fmtMs(r.p95_ms)], ['p99', (r) => fmtMs(r.p99_ms)],
    ['p99.9', (r) => fmtMs(r.p999_ms)], ['max', (r) => fmtMs(r.max_ms)],
    ['cas', (r) => r.cas_failures], ['err', (r) => r.other_errors],
  ];
  let resultsTable = null;
  function appendLevelResult(ev) {
    if (!resultsTable) {
      resultsTable = h('table', { class: 'results' },
        h('thead', {}, h('tr', {}, h('th', {}, 'target'), resultCols.map(([name]) => h('th', {}, name)))),
        h('tbody'));
      resultsBox.append(h('div', { class: 'card' }, h('h2', {}, 'Level results'), resultsTable));
    }
    const tbody = resultsTable.querySelector('tbody');
    let first = true;
    for (const t of state.hello.targets) {
      const r = ev.targets[String(t.id)];
      if (!r) continue;
      tbody.append(h('tr', { class: first ? 'lvl-first' : '' },
        h('td', { class: 'tname' }, h('span', { class: 'dot', style: { '--tcolor': targetColor(t.id), marginRight: '6px' } }), t.name),
        resultCols.map(([, fn], ci) => h('td', { class: ci >= 8 && fn(r) > 0 ? 'num-bad' : '' }, String(fn(r))))));
      first = false;
    }
  }

  // --- event handlers ---
  const handlers = {
    hello(ev) {
      state.hello = ev;
      state.strategy = ev.workload.strategy;
      workloadNote.textContent = `${ev.workload.strategy} · sweep ${ev.levels.join(', ')} · ${ev.workload.duration_sec}s/level`;
      buildTiles(ev.targets);
      buildCharts(ev.targets);
      renderLevels();
      cancelBtn.style.display = '';
      badge.className = 'badge running';
      badge.textContent = 'running';
    },
    target_ready(ev) {
      const t = state.hello?.targets.find((x) => x.id === ev.target);
      if (t && t._tile) t._tile.label.textContent = `${ev.label} · ${ev.object_format}${ev.nodes > 1 ? ` · ${ev.nodes} nodes` : ''}`;
    },
    level_start(ev) {
      state.curLevel = ev;
      const t0 = Date.parse(ev.at) / 1000;
      state.warmups.push({ from: t0, to: t0 + ev.warmup_sec });
      renderLevels();
    },
    bucket(ev) {
      if (!state.hello) return;
      const targets = state.hello.targets;
      const isClone = state.strategy === 'clone';
      const vals = targets.map((t) => ev.targets[String(t.id)] || null);

      // throughput (+ dashed clone series for session)
      const tputVals = vals.map((v) => (v ? (isClone ? v.clone_ok || 0 : v.ok) : null));
      if (state.strategy === 'session') tputVals.push(...vals.map((v) => (v ? v.clone_ok || 0 : null)));
      charts.tput.push(ev.t, tputVals);

      // latency rows retained for percentile switching
      const latVals = vals.map((v) => v && (isClone ? v.clone_ok : v.ok) > 0
        ? (isClone
          ? { p50: v.clone_p50_ms, p95: v.clone_p95_ms, p99: v.clone_p99_ms }
          : { p50: v.p50_ms, p95: v.p95_ms, p99: v.p99_ms })
        : null);
      state.latRows.push({ ts: ev.t, vals: latVals });
      charts.lat.push(ev.t, latVals.map((v) => (v ? v[pct] : null)));

      charts.err.push(ev.t, [
        ...vals.map((v) => (v ? (isClone ? v.clone_err || 0 : v.err) : null)),
        ...vals.map((v) => (v ? v.cas : null)),
      ]);

      // tiles
      targets.forEach((t, i) => {
        const v = vals[i];
        if (!v || !t._tile) return;
        const tot = state.totals[t.id];
        tot.ok += isClone ? v.clone_ok || 0 : v.ok;
        tot.err += (isClone ? v.clone_err || 0 : v.err);
        tot.cas += v.cas || 0;
        t._tile.ops.textContent = fmtNum(isClone ? v.clone_ok || 0 : v.ok);
        t._tile.p95.textContent = fmtMs(latVals[i] ? latVals[i].p95 : null) || '–';
        t._tile.errs.textContent = fmtNum(tot.err + tot.cas);
        t._tile.errs.style.color = tot.err + tot.cas > 0 ? 'var(--critical)' : '';
      });
    },
    level_result(ev) { appendLevelResult(ev); },
    target_error(ev) {
      banners.append(h('div', { class: 'banner error' },
        `✖ ${targetName(ev.target)}: ${ev.message}${ev.fatal ? ' — target removed from the run' : ''}`));
      const t = state.hello?.targets.find((x) => x.id === ev.target);
      if (t && t._tile && ev.fatal) {
        t._tile.root.classList.add('dead');
        t._tile.err.style.display = '';
        t._tile.err.textContent = ev.message;
      }
    },
    run_done(ev) {
      state.done = ev;
      badge.className = `badge ${ev.state}`;
      badge.textContent = ev.state;
      cancelBtn.style.display = 'none';
      renderLevels();
      tickProgress();
      if (ev.results_file) {
        banners.append(h('div', { class: 'banner' },
          'Results saved to ', h('code', {}, ev.results_file), ' — ',
          h('a', { href: '#history', style: { color: 'var(--accent)' } }, 'compare in history')));
      }
      if (es) { es.close(); es = null; }
    },
  };

  function targetName(id) {
    const t = state.hello?.targets.find((x) => x.id === id);
    return t ? t.name : (id < 0 ? 'run' : `target ${id}`);
  }

  es = openRunStream(runId, handlers);
  es.onerror = () => { if (!state.done) { badge.className = 'badge'; badge.textContent = 'reconnecting…'; } };
  es.onopen = () => { if (!state.done && state.hello) { badge.className = 'badge running'; badge.textContent = 'running'; } };
  ticker = setInterval(tickProgress, 500);

  return () => {
    if (es) es.close();
    clearInterval(ticker);
    Object.values(charts).forEach((c) => c.destroy && c.destroy());
  };
}

// Runs list: active + recent runs of this server session.

import { h } from '../dom.js';
import { api } from '../api.js';

export function renderRuns(app) {
  const box = h('div', { class: 'card' }, h('div', { class: 'empty' }, 'Loading…'));
  app.append(h('h1', {}, 'Runs'), h('p', { class: 'sub' }, 'Active and recent runs of this server session. Older runs live in History.'), box);

  api.listRuns().then((runs) => {
    box.innerHTML = '';
    if (!runs || !runs.length) {
      box.append(h('div', { class: 'empty' }, 'No runs yet — start one from ', h('a', { href: '#new', style: { color: 'var(--accent)' } }, 'New run'), '.'));
      return;
    }
    for (const r of runs) {
      box.append(h('div', { class: 'hist-row' },
        h('a', { class: 'file', href: `#run/${r.id}`, style: { color: 'var(--ink)' } }, r.id),
        h('span', { class: `badge ${r.state}` }, r.state),
        h('span', { class: 'meta' }, `${r.workload.strategy} · sweep ${r.levels.join(',')} · ${r.targets.map((t) => t.name).join(' vs ')}`),
        h('span', { class: 'spacer' }),
        h('span', { class: 'meta' }, new Date(r.started_at).toLocaleString())));
    }
  }).catch((err) => {
    box.innerHTML = '';
    box.append(h('div', { class: 'banner error' }, String(err.message || err)));
  });
}

// History: browse results/*.json (CLI and server runs alike) and overlay any
// selection as sweep curves — ops/s vs concurrency and p95 vs concurrency.
// A single selected run with a stored live series also replays its timeline.

import { h } from '../dom.js';
import { api } from '../api.js';
import { sweepChart, timeChart, targetColor, fmtNum, fmtMs } from '../charts.js';

export function renderHistory(app) {
  const selected = new Map(); // file → doc
  const listBox = h('div', { class: 'card' }, h('div', { class: 'empty' }, 'Loading…'));
  const compareBox = h('div');
  let liveCharts = [];

  app.append(
    h('h1', {}, 'History'),
    h('p', { class: 'sub' }, 'Every stored result — CLI and GUI runs alike. Select runs to overlay their sweep curves.'),
    listBox, compareBox);

  async function toggle(file, checked) {
    if (checked) {
      try { selected.set(file, await api.historyDoc(file)); }
      catch (err) { alert(String(err.message || err)); return; }
    } else {
      selected.delete(file);
    }
    renderCompare();
  }

  function seriesList() {
    // One series per (run, target): identity is stable across both charts.
    const out = [];
    for (const [file, doc] of selected) {
      for (const t of doc.targets || []) {
        if (!t.levels || !t.levels.length) continue;
        const runTag = selected.size > 1 ? ` (${doc.run_id || file})` : '';
        out.push({ label: `${t.name || 'target'}${runTag}`, target: t });
      }
    }
    return out.map((s, i) => ({ ...s, color: targetColor(i) }));
  }

  function renderCompare() {
    for (const c of liveCharts) c.destroy && c.destroy();
    liveCharts = [];
    compareBox.innerHTML = '';
    const series = seriesList();
    if (!series.length) return;

    const mkCard = (title, note) => {
      const el = h('div');
      compareBox.append(h('div', { class: 'card chart-card' },
        h('div', { class: 'chart-head' }, h('h2', {}, title), h('span', { class: 'u-note' }, note)), el));
      return el;
    };

    liveCharts.push(sweepChart(mkCard('Throughput vs concurrency', 'successful ops/s per level (x is log₂)'), {
      seriesData: series.map((s) => ({
        label: s.label, color: s.color,
        points: s.target.levels.map((l) => [l.concurrency, l.ops_per_sec]),
      })),
      unit: fmtNum,
    }));
    liveCharts.push(sweepChart(mkCard('p95 latency vs concurrency', 'per-op p95 in the measured window'), {
      seriesData: series.map((s) => ({
        label: s.label, color: s.color,
        points: s.target.levels.map((l) => [l.concurrency, l.p95_ms]),
      })),
      unit: fmtMs,
    }));

    // Timeline replay when exactly one run is selected and it stored series.
    if (selected.size === 1) {
      const doc = [...selected.values()][0];
      const withSeries = (doc.targets || []).filter((t) => t.series && t.series.length);
      if (withSeries.length) {
        const tputEl = mkCard('Timeline replay — throughput', 'stored 1s buckets from the live run');
        const latEl = mkCard('Timeline replay — p95 latency', 'rolling 10s window as recorded');
        const colors = new Map(seriesList().map((s) => [s.target, s.color]));
        const ts = [...new Set(withSeries.flatMap((t) => t.series.map((p) => p.t)))].sort((a, b) => a - b);
        const mkRows = (val) => ts.map((x) => [x, ...withSeries.map((t) => {
          const p = t.series.find((q) => q.t === x);
          return p ? val(p) : null;
        })]);
        const tput = timeChart(tputEl, { series: withSeries.map((t) => ({ label: t.name, color: colors.get(t) || targetColor(0) })), unit: fmtNum });
        tput.setAll(mkRows((p) => p.ok));
        const lat = timeChart(latEl, { series: withSeries.map((t) => ({ label: t.name, color: colors.get(t) || targetColor(0) })), unit: fmtMs });
        lat.setAll(mkRows((p) => (p.ok > 0 ? p.p95 : null)));
        liveCharts.push(tput, lat);
      }
    }
  }

  api.history().then((items) => {
    listBox.innerHTML = '';
    if (!items || !items.length) {
      listBox.append(h('div', { class: 'empty' }, 'No results yet. Finished runs land here as JSON docs.'));
      return;
    }
    for (const it of items) {
      const cb = h('input', { type: 'checkbox', style: { width: 'auto' }, onchange: (e) => toggle(it.file, e.target.checked) });
      listBox.append(h('div', { class: 'hist-row' },
        cb,
        h('span', { class: 'file' }, it.run_id || it.file),
        it.state ? h('span', { class: `badge ${it.state}` }, it.state) : null,
        h('span', { class: 'meta' }, `${it.strategy} · ${(it.targets || []).join(' vs ') || '—'} · ${it.levels} level${it.levels === 1 ? '' : 's'}`),
        h('span', { class: 'spacer' }),
        h('span', { class: 'meta' }, new Date(it.mtime).toLocaleString())));
    }
  }).catch((err) => {
    listBox.innerHTML = '';
    listBox.append(h('div', { class: 'banner error' }, String(err.message || err)));
  });

  return () => { for (const c of liveCharts) c.destroy && c.destroy(); };
}

